192	func (m Model) handleResultsState(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
193		switch msg.String() {
194		case "esc":
195			// If no origin view is set (opened directly), go back to the scan form
196			if m.OriginView == "" {
197				m.state = StateInput
198				return m, nil
199			}
200			return m, func() tea.Msg { return BackToOriginMsg{Origin: m.OriginView} }
201		case "enter":
202			if finding, ok := m.findingsTable.Selected(); ok {
203				// The details view is about a finding, not about a row index — an
204				// index would name a different one the moment the list changed
205				// under it, which is how workspaces got D24.
206				m.selectedFinding = &finding
207				m.state = StateDetails
208				m.detailsViewport.Width = m.width
209				m.detailsViewport.Height = m.height
210				m.detailsViewport.SetContent(m.buildDetailsContent())
211				m.detailsViewport.GotoTop()
212			}
213			return m, nil
214		case "ctrl+r":
215			m.state = StateInput
216			m.activeTab = TabCVE
217			m.severityFilter = "all"
218			return m, nil
219		case "tab":
220			m.switchTab((m.activeTab + 1) % 4)
221			return m, nil
222		case "shift+tab":
223			m.switchTab((m.activeTab + 3) % 4)
224			return m, nil
225		case "1":
226			m.switchTab(TabCVE)
227			return m, nil
228		case "2":
229			m.switchTab(TabSecrets)
230			return m, nil
231		case "3":
232			m.switchTab(TabLicense)
233			return m, nil
234		case "4":
235			m.switchTab(TabMisconfig)
236			return m, nil
237		case ".":
238			if m.activeTab == TabCVE || m.activeTab == TabLicense || m.activeTab == TabMisconfig {
239				m.cycleSeverityFilter()
240				m.updateFindingsTable()
241			}
242			return m, nil
243		case "i":
244			m.handleIgnoreSecret()
245			return m, nil
246		case "up", "down", "k", "j", "pgup", "pgdown", "g", "home", "G", "end":
247			return m, m.findingsTable.Update(msg)
248		}
249		return m, nil
250	}
251	
252	// cycleSeverityFilter cycles through severity filter options
253	func (m *Model) cycleSeverityFilter() {
254		filters := []string{"all", "critical", "high", "medium", "low"}
255		for i, f := range filters {
256			if f == m.severityFilter {
257				m.severityFilter = filters[(i+1)%len(filters)]
258				return
259			}
260		}
261		m.severityFilter = "all"
262	}
