1	package app
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/anthnel/devdesk/internal/ui/shortcut"
8		"github.com/anthnel/devdesk/internal/ui/theme"
9		"github.com/charmbracelet/lipgloss"
10	)
11	
12	// HeaderView est l'interface que chaque vue doit implémenter pour fournir les données du header
13	type HeaderView interface {
14		GetShortcuts() shortcut.Shortcuts
15		GetTitle() string
16		GetIcon() string
17		GetHeaderInfo(context string) []shortcut.HeaderInfo
18	}
19	
20	// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
21	// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
22	type FooterView interface {
23		GetFooterHeight() int          // current footer height in lines (0 if no footer)
24		RenderFooter(width int) string // rendered footer content
25	}
26	
27	// headerMinHeight est la hauteur fixe du header (sans la ligne de commande).
28	const headerMinHeight = 7
29	
30	// ASCII logo for the header
31	var logoLines = []string{
32		`    ____            ____            __  `,
33		`   / __ \___ _   __/ __ \___  _____/ /__`,
34		`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
35		` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
36		`/_____/\___/|___/_____/\___/____/_/|_|  `,
37	}
38	
39	const logoWidth = 40 // max width of a logo line
40	
41	// renderHeader generates the header (fixed height) followed by the command line (1 line).
42	func (a *App) renderHeader() string {
43		if view, ok := a.views[a.currentView]; ok {
44			if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
45				shortcuts := headerView.GetShortcuts()
46				info := headerView.GetHeaderInfo(a.currentContext)
47	
48				header := renderHeaderContent(info, shortcuts, a.width)
49	
50				pad := theme.Bg(" ")
51				var cmdLine string
52				if a.commandMode {
53					cmdLine = pad + theme.CommandLineStyle.Width(a.width-2).Render(a.renderCommandLineWithCompletion()) + pad
54				} else {
55					cmdLine = pad + theme.CommandLineInactiveStyle.Width(a.width-2).Render(":") + pad
56				}
57	
58				return header + "\n" + theme.EmptyLineBg(a.width) + "\n" + cmdLine
59			}
60		}
61	
62		return ""
63	}
64	
65	// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
66	// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
67	func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
68		innerWidth := width - 2 // 1 padding each side
69	
70		// Column widths
71		col1Width := innerWidth / 4
72		col3Width := logoWidth
73		col2Width := innerWidth - col1Width - col3Width
74		if col2Width < 0 {
75			col2Width = 0
76		}
77	
78		// Build column 1: key-value info lines
79		col1Lines := buildInfoLines(info, col1Width)
80	
81		// Build column 2: shortcuts
82		col2Lines := buildShortcutLines(shortcuts, col2Width)
83	
84		// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
85		col3Lines := buildLogoLines(col3Width)
86	
87		// Assemble rows
88		rows := make([]string, headerMinHeight)
89		for i := 0; i < headerMinHeight; i++ {
90			c1 := ""
91			if i < len(col1Lines) {
92				c1 = col1Lines[i]
93			}
94			c2 := ""
95			if i < len(col2Lines) {
96				c2 = col2Lines[i]
97			}
98			c3 := ""
99			if i < len(col3Lines) {
100				c3 = col3Lines[i]
101			}
102	
103			pad := theme.Bg(" ")
104			row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
105			rows[i] = row
106		}
107	
108		return strings.Join(rows, "\n")
109	}
110	
111	// buildInfoLines builds the key-value info lines for column 1, aligning values on the longest key
112	func buildInfoLines(info []shortcut.HeaderInfo, _ int) []string {
113		// Find max key length for alignment
114		maxKeyLen := 0
115		for _, h := range info {
116			if len(h.Key) > maxKeyLen {
117				maxKeyLen = len(h.Key)
118			}
119		}
120	
121		lines := make([]string, headerMinHeight)
122		for i := 0; i < headerMinHeight; i++ {
123			if i < len(info) {
124				// Pad key to maxKeyLen so all ": " align
125				paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
126				label := theme.HeaderKeyStyle.Render(paddedKey + ": ")
127	
128				value := info[i].Value
129				if info[i].Style.GetForeground() != lipgloss.Color("") {
130					value = info[i].Style.Background(theme.ColorBackground).Render(value)
131				} else {
132					value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
133				}
134	
135				lines[i] = label + value
136			} else {
137				lines[i] = ""
138			}
139		}
140		return lines
141	}
142	
143	// buildShortcutLines builds the shortcut lines for column 2
144	func buildShortcutLines(shortcuts shortcut.Shortcuts, col2Width int) []string {
145		if len(shortcuts) == 0 {
146			lines := make([]string, headerMinHeight)
147			for i := range lines {
148				lines[i] = ""
149			}
150			return lines
151		}
152	
153		// Split shortcuts into columns of maxLine items
154		columns := splitArrayIntoChunks(shortcuts, headerMinHeight)
155	
156		// Get rendered lines for each column
157		var allColumnLines [][]string
158		for i, col := range columns {
159			minH := 0
160			if i == 0 {
161				minH = headerMinHeight
162			}
163			allColumnLines = append(allColumnLines, renderShortcutsColumnLines(col, minH))
164		}
165	
166		// Normalize heights
167		for i := range allColumnLines {
168			for len(allColumnLines[i]) < headerMinHeight {
169				allColumnLines[i] = append(allColumnLines[i], "")
170			}
171		}
172	
173		// Calculate column widths
174		colWidths := make([]int, len(allColumnLines))
175		for ci, colLines := range allColumnLines {
176			for _, line := range colLines {
177				if w := lipgloss.Width(line); w > colWidths[ci] {
178					colWidths[ci] = w
179				}
180			}
181		}
182	
183		sep := "  "
184		sepRendered := theme.Bg(sep)
185	
186		// Build each row
187		result := make([]string, headerMinHeight)
188		for row := 0; row < headerMinHeight; row++ {
189			var line string
190			for ci, colLines := range allColumnLines {
191				if ci > 0 {
192					line += sepRendered
193				}
194				if row < len(colLines) {
195					line += theme.PadWithBg(colLines[row], colWidths[ci])
196				} else {
197					line += theme.EmptyLineBg(colWidths[ci])
198				}
199			}
200			// Clip to the column. PadWithBg cannot do this — it pads a short line and
201			// returns a long one untouched — and a plain slice would cut an escape
202			// sequence in half, which is the hazard Rule 122 is about. MaxWidth
203			// truncates on rune boundaries and leaves the sequences intact.
204			if col2Width > 0 {
205				line = lipgloss.NewStyle().MaxWidth(col2Width).Render(line)
206			}
207			result[row] = line
208		}
209	
210		return result
