12	// Scan runs its stages concurrently against one runner, so a test says what
13	// each stage answers rather than what the next call answers.
14	
15	type stageReply struct {
16		stdout string
17		err    error
18	}
19	
20	// stageOf names the stage an invocation belongs to, from the invocation alone —
21	// which is the only thing the runner sees.
22	//
23	// "secret" and "trivy-secret" are separate: secret scanning is the one option
24	// served by both tools, Gitleaks over git history and Trivy over the target's
25	// content, and only Trivy's half applies to an image.
26	func stageOf(tc toolCmd) string {
27		s := tc.String()
28		switch {
29		case strings.Contains(s, "cyclonedx"):
30			return "sbom"
31		case strings.Contains(s, "--scanners license"):
32			return "license"
33		case strings.Contains(s, "--scanners misconfig"):
34			return "misconfig"
35		case strings.Contains(s, "--scanners secret"):
36			return "trivy-secret"
37		case strings.HasPrefix(s, "gitleaks"):
38			return "secret"
39		default:
40			return "vuln"
41		}
42	}
43	
44	func byStage(t *testing.T, replies map[string]stageReply) *scriptedRunner {
45		t.Helper()
46		r := &scriptedRunner{}
47		r.reply = func(tc toolCmd) ([]byte, error) {
48			stage := stageOf(tc)
49			reply, scripted := replies[stage]
50			if !scripted {
51				t.Errorf("the %s stage ran although nothing was scripted for it: %s", stage, tc)
52			}
53			return []byte(reply.stdout), reply.err
54		}
55		useRunner(t, r)
56		return r
57	}
58	
59	// stagesRun reports which stages the runner was actually asked to execute.
60	func stagesRun(r *scriptedRunner) []string {
61		r.mu.Lock()
62		defer r.mu.Unlock()
63		seen := make([]string, 0, len(r.calls))
64		for _, c := range r.calls {
65			seen = append(seen, stageOf(c))
66		}
67		sort.Strings(seen)
68		return seen
69	}
