1	package datatable
2	
3	// Rule 116: the column widths must sum to exactly the space available, or the
4	// selected row stops short of the right viewport border.
5	//
6	// Every view enforced that the same way — last column absorbs the remainder —
7	// and several then applied a per-column `max(…, floor)` *after* the remainder
8	// was computed, which silently pushes the sum back over. `workspaces` overflows
9	// by 34 columns on a 120-wide terminal that way.
10	//
11	// The fix is not a better clamp. It is to distribute the shortfall across the
12	// columns instead of letting each one defend its own floor: a floor that cannot
13	// be honoured has to be given up by somebody, and deciding that here is what
14	// makes the invariant hold at every width rather than most of them.
15	
16	// borderWidth is the viewport's two vertical borders.
17	const borderWidth = 2
18	
19	// cellPadding is what bubbles/table adds per column — Padding(0, 1).
20	const cellPadding = 2
21	
22	// availableFor returns the width the columns have to share, given the full
23	// viewport width. Negative when the terminal cannot even hold the borders and
24	// the padding, which the solver reads as "no room at all".
25	func availableFor(viewportWidth, numColumns int) int {
26		return viewportWidth - borderWidth - numColumns*cellPadding
27	}
28	
29	// solveWidths distributes available across the columns.
30	//
31	// Fixed columns (Flex == 0) ask for MinWidth. Flexible ones ask for MinWidth
32	// and share whatever is left in proportion to their Flex weight. When there is
33	// not enough for everyone, the shortfall comes out of the flexible columns
34	// first and the fixed ones only after — a fixed column is fixed because its
35	// content has a known size, so it is the last thing worth truncating.
36	//
37	// The result always sums to exactly max(available, 0).
38	func solveWidths[T any](columns []Column[T], available int) []int {
39		widths := make([]int, len(columns))
40		if len(columns) == 0 || available <= 0 {
41			return widths
42		}
43	
44		total := 0
45		for i, c := range columns {
46			widths[i] = max(c.MinWidth, 0)
47			total += widths[i]
48		}
49	
50		switch {
51		case total < available:
52			grow(columns, widths, available-total)
53		case total > available:
54			shrink(columns, widths, total-available)
55		}
56		return widths
57	}
58	
59	// grow hands the surplus to the flexible columns by weight, giving the last one
60	// the rounding remainder so the sum is exact. With no flexible column the last
61	// column absorbs it, which is what every view did by hand.
62	func grow[T any](columns []Column[T], widths []int, surplus int) {
63		weight := 0
64		last := -1
65		for i, c := range columns {
66			if c.Flex > 0 {
67				weight += c.Flex
68				last = i
69			}
70		}
71		if weight == 0 {
72			widths[len(widths)-1] += surplus
73			return
74		}
75	
76		given := 0
77		for i, c := range columns {
78			if c.Flex <= 0 || i == last {
79				continue
80			}
81			share := surplus * c.Flex / weight
82			widths[i] += share
83			given += share
84		}
85		widths[last] += surplus - given
86	}
87	
88	// shrink reclaims the shortfall, taking from the flexible columns before the
89	// fixed ones and from the widest before the narrowest, so that one long column
90	// gives way before several short ones become unreadable.
91	func shrink[T any](columns []Column[T], widths []int, shortfall int) {
92		shortfall = takeFrom(widths, order(columns, true), shortfall)
93		takeFrom(widths, order(columns, false), shortfall)
94	}
95	
96	// order returns the column indices to reclaim from, widest first, restricted to
97	// the flexible ones or the fixed ones.
98	func order[T any](columns []Column[T], flexible bool) []int {
99		var idx []int
100		for i, c := range columns {
101			if (c.Flex > 0) == flexible {
102				idx = append(idx, i)
103			}
104		}
105		return idx
106	}
107	
108	// takeFrom removes shortfall from the given columns one unit at a time, always
109	// from the widest, and returns what could not be taken. One unit at a time
110	// keeps it exact and level: no column is emptied while another stays wide.
111	func takeFrom(widths []int, idx []int, shortfall int) int {
112		for shortfall > 0 {
113			widest, at := 0, -1
