package security

import (
	"fmt"
	"log"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// Update handles messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	// Handle confirm modal messages first (before passing to modal)
	switch msg := msg.(type) {
	case sharedcomponents.ConfirmModalYesMsg:
		// User confirmed to ignore the secret
		if m.findingToIgnore != nil {
			finding := *m.findingToIgnore
			targetDir := m.targetPath
			m.confirmModal = nil
			m.findingToIgnore = nil
			return m, func() tea.Msg {
				err := scan.AddToGitleaksIgnore(targetDir, finding)
				return SecretIgnoredMsg{Finding: finding, Error: err}
			}
		}
		m.confirmModal = nil
		m.findingToIgnore = nil
		return m, nil

	case sharedcomponents.ConfirmModalNoMsg:
		// User cancelled
		m.confirmModal = nil
		m.findingToIgnore = nil
		return m, nil

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		// Widths and height in one call; SetHeight accounts for the header row
		// internally, so m.height goes through as it is. Rows no longer depend
		// on the width — bubbles truncates each cell to its own column — so
		// there is nothing to rebuild here.
		m.findingsTable.Resize(m.width, max(m.height, 5))
		m.inventory.Resize(m.width, max(m.height, 5))
		// Update details viewport size and refresh content
		m.detailsViewport.Width = msg.Width
		m.detailsViewport.Height = msg.Height
		if m.state == StateDetails {
			m.detailsViewport.SetContent(m.buildDetailsContent())
		}
		return m, nil

	case tea.KeyMsg:
		// Pass key messages to confirm modal if active
		if m.confirmModal != nil {
			var cmd tea.Cmd
			m.confirmModal, cmd = m.confirmModal.Update(msg)
			return m, cmd
		}
		return m.handleKeyMsg(msg)

	case DepsCheckedMsg:
		m.deps = msg.Deps
		return m, nil

	case ScanCompleteMsg:
		return m.handleScanComplete(msg)

	case SecretIgnoredMsg:
		if msg.Error != nil {
			log.Printf("ERROR [security] ignore secret %s: %v", msg.Finding.File, msg.Error)
			m.statusMessage = "Failed to ignore secret — check logs"
		} else {
			m.statusMessage = fmt.Sprintf("Added %s to .gitleaksignore", msg.Finding.File)
		}
		return m, clearStatusCmd()

	case clearStatusMsg:
		m.statusMessage = ""
		return m, nil

	case SelectionResultMsg:
		m.targetPath = msg.Path
		m.targetInput.SetValue(msg.Path)
		return m, nil

	case SelectionCancelledMsg:
		return m, nil

	case StartScanMsg:
		return m.startScan()

	case ScanProgressMsg:
		return m.handleScanProgress(msg)

	case InventoryLoadedMsg:
		return m.handleInventoryLoaded(msg)

	case InventoryResultLoadedMsg:
		return m.handleInventoryResultLoaded(msg)

	case InventoryScanFinishedMsg:
		return m.handleInventoryScanFinished(msg)

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	}

	return m, nil
}

// handleSpinnerTick advances the spinner while something is actually spinning.
//
// The inventory counts as spinning too: its frame is a table cell rather than a
// scanning screen, and a frame that never advances reads as a hung scan. Its
// rows carry the frame, so they are restamped — but only then, since SetItems
// re-filters and re-sorts and there is no reason to do that sixty times a second
// for a table with nothing running.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	scanningInventory := m.inventoryScanning()
	if m.state != StateScanning && !scanningInventory {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	if scanningInventory {
		m.setInventory(m.inventory.Items())
	}
	return m, cmd
}

// handleKeyMsg processes keyboard input
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch m.state {
	case StateInventory:
		return m.handleInventoryState(msg)
	case StateInput:
		return m.handleInputState(msg)
	case StateScanning:
		if msg.String() == "esc" || msg.String() == "ctrl+c" {
			return m.cancelCurrentScan()
		}
		return m, nil
	case StateResults:
		return m.handleResultsState(msg)
	case StateDetails:
		return m.handleDetailsState(msg)
	}
	return m, nil
}

