22	// back from the cache, which is how findings reach the screen now.
23	func TestNewWithPreloadedResultOpensOnTheResults(t *testing.T) {
24		result := resultFixture()
25	
26		m := feed(t, NewWithPreloadedResult(testConfig(), result), tea.WindowSizeMsg{Width: 160, Height: 30})
