package security

import (
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// targetKind tells the two caches apart. It decides which loader `enter` uses
// and which TargetType a rescan runs with, so it is carried rather than
// re-derived from the name — an absolute path and a "repo:tag" are not reliably
// distinguishable, and guessing wrong scans a directory as an image.
type targetKind int

const (
	kindImage targetKind = iota
	kindRepo
)

// scanTarget is one row of the inventory: something that has been scanned, what
// the scan found, and when.
//
// Kind, the display name and whether a rescan is running now live on none of
// the cache entries, which is why the decoration goes on the row rather than
// being looked up from the model — the same reason imageRow exists. The columns
// are built once, in New, so their Cell functions have nothing to reach back
// into, and each count column sorts by the number it prints.
type scanTarget struct {
	Kind      targetKind
	Name      string // the cache key: "repo:tag", or the absolute repository path
	Counts    scan.SeverityCounts
	ScannedAt time.Time
	// Scanned is false between a ctrl+a purge and the scan that replaces it.
	// The target is still known — it is the counts that are not.
	Scanned      bool
	Scanning     bool
	Failed       bool
	SpinnerFrame string
}

// inventoryColumnCritical is the column the inventory opens sorted by,
// descending: the target with the most critical findings is the one the view
// exists to surface.
const inventoryColumnCritical = 1

// displayName is what the Target column shows: the image reference as it is
// cached, or the repository path with the home directory folded back to "~".
// The cache key stays the value everything else uses, so folding here cannot
// reach a loader or a scanner.
func (t scanTarget) displayName() string {
	if t.Kind == kindImage {
		return theme.IconDocker + " " + t.Name
	}
	return theme.IconWorkspace + " " + shortenHome(t.Name)
}

// shortenHome replaces the home directory prefix with "~". It is the inverse of
// the expansion the workspaces view does on the configured root.
func shortenHome(path string) string {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return path
	}
	rel, err := filepath.Rel(home, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return path
	}
	if rel == "." {
		return "~"
	}
	return "~" + string(filepath.Separator) + rel
}

// countColumnWidth holds the four severity columns to one width. datatable
// already reserves room for the sort arrow, which would give CRIT and HIGH six
// cells and MED and LOW five — four adjacent columns of the same kind, ragged.
const countColumnWidth = 6

// countColumn builds one of the four severity columns. A purged row prints "-"
// rather than "0": nothing was found and nothing is known are different answers,
// and zero is the one a user reads as "clean".
func countColumn(title string, get func(scan.SeverityCounts) int) datatable.Column[scanTarget] {
	return datatable.Column[scanTarget]{
		Title: title, MinWidth: countColumnWidth,
		Cell: func(t scanTarget) string {
			if !t.Scanned {
				return "-"
			}
			return strconv.Itoa(get(t.Counts))
		},
		Less: func(a, b scanTarget) bool { return get(a.Counts) < get(b.Counts) },
	}
}

// inventoryScannedCell reports the scan state: the spinner while one runs, an
// error icon when the last attempt failed, otherwise how long ago it succeeded
// (Rule 127). Plain text throughout — Rule 122.
func inventoryScannedCell(t scanTarget) string {
	switch {
	case t.Scanning:
		return t.SpinnerFrame + "scanning"
	case t.Failed:
		return theme.IconError + " error"
	case t.Scanned:
		return theme.TimeAgo(t.ScannedAt)
	}
	return "-"
}

// inventoryColumns describes the inventory table.
func inventoryColumns() []datatable.Column[scanTarget] {
	return []datatable.Column[scanTarget]{
		{
			Title: "Target", MinWidth: 24, Flex: 1,
			Cell: func(t scanTarget) string { return t.displayName() },
			Less: func(a, b scanTarget) bool {
				return strings.ToLower(a.Name) < strings.ToLower(b.Name)
			},
			// The cache key, not the displayed name: a query for the full path of
			// a repository has to match the row that folds it to "~".
			Search: func(t scanTarget) string { return t.Name },
		},
		countColumn("CRIT", func(c scan.SeverityCounts) int { return c.Critical }),
		countColumn("HIGH", func(c scan.SeverityCounts) int { return c.High }),
		countColumn("MED", func(c scan.SeverityCounts) int { return c.Medium }),
		countColumn("LOW", func(c scan.SeverityCounts) int { return c.Low }),
		{
			Title: "Scanned", MinWidth: 14,
			Cell: inventoryScannedCell,
			Less: func(a, b scanTarget) bool { return a.ScannedAt.Before(b.ScannedAt) },
		},
	}
}

// newInventoryTable builds the inventory table.
func newInventoryTable() datatable.Model[scanTarget] {
	return datatable.New(datatable.Config[scanTarget]{
		Columns:    inventoryColumns(),
		SortColumn: inventoryColumnCritical,
		SortDesc:   true,
	})
}

package scan

import (
	"fmt"
	"net/url"
	"path/filepath"
	"strings"
)

// Building a Trivy invocation is pure: the same inputs produce the command that
// is run and the command that is shown. Keeping the two derived from one
// builder is what stops them drifting apart (§1.3 D19).

// containerScanPath is where a scanned directory is mounted inside the tool's
// container, so the argument passed to the tool is never the host path.
const containerScanPath = "/scan"

// containerOutputPath is where a writable output directory is mounted.
const containerOutputPath = "/output"

// dockerSocketMount lets a containerised Trivy inspect images held by the host
// daemon. It is a broad grant, so it is only made when there is no Trivy server
// to do the work instead.
const dockerSocketMount = "/var/run/docker.sock:/var/run/docker.sock:ro"

// serverAddr normalises the configured Trivy server address, refusing one Trivy
// cannot use.
//
// Trivy parses this as a URL and fails the entire scan when it cannot. A single
// stray ":" in the field — which is easy to get, since a bare ":" typed while
// the field has focus is a character rather than the command line (§3.7) —
// produces
//
//	FATAL flag error: unable to convert flags to options:
//	invalid server address format: parse ":": missing protocol scheme
//
// a message naming neither DevDesk nor the setting it came from. Worse, the
// field is persisted on every option toggle, so one keystroke breaks every
// later scan from every view until it is found in the config file.
//
// Surrounding space is not an address, so it trims to nothing and client-server
// mode is simply off. Anything else that is not an absolute URL is refused
// here, where the message can say where to fix it.
// ValidateTrivyServer reports whether a Trivy server address can be used, so a
// form can refuse it while the user is still looking at the field rather than
// letting the failure surface as a scan warning minutes later.
func ValidateTrivyServer(server string) error {
	_, err := serverAddr(server)
	return err
}

func serverAddr(server string) (string, error) {
	trimmed := strings.TrimSpace(server)
	if trimmed == "" {
		return "", nil
	}
	// Hostname() rather than Host: "http://:" parses with a Host of ":" and no
	// hostname at all, which is not somewhere a request can be sent.
	parsed, err := url.Parse(trimmed)
	if err != nil || parsed.Scheme == "" || parsed.Hostname() == "" {
		return "", fmt.Errorf(
			"trivy server address %q is not a URL (want http://host:port) — fix or clear scan.trivy_server", trimmed)
	}
	return trimmed, nil
}

// trivyArgs builds a vulnerability or license scan.
func trivyArgs(target string, targetType TargetType, licenseMode bool, tool ToolSpec,
	server string, ignoreUnfixed, ignoreEOL bool) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json"}
		if licenseMode {
			args = append(args, "--scanners", "license")
		} else {
			args = append(args, "--scanners", "vuln")
		}
	case TargetImage:
		// --scanners vuln explicitly: Trivy's default for an image is
		// "vuln,secret", so this stage was running the secret scanner on every
		// image scan and throwing its output away. Secrets are the secret
		// stage's job, and asking for them twice would report each one twice.
		args = []string{"image", "--format", "json", "--scanners", "vuln"}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}
	if ignoreUnfixed {
		args = append(args, "--ignore-unfixed")
	}
	if ignoreEOL {
		args = append(args, "--ignore-status", "end_of_life")
	}

	return wrapTrivy(args, target, targetType, tool, server), nil
}

// trivySecretArgs builds a secret scan. Like misconfiguration, it reads content
// rather than a package manifest, so it applies to both target types — which is
// what gives an image scan a secret stage at all, Gitleaks being directory-only.
func trivySecretArgs(target string, targetType TargetType, tool ToolSpec, server string) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json", "--scanners", "secret"}
	case TargetImage:
		args = []string{"image", "--format", "json", "--scanners", "secret"}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}

	// No --ignore-status: end_of_life describes a package's support window and
	// says nothing about a secret sitting in a file.
	return wrapTrivy(args, target, targetType, tool, server), nil
}

// trivyMisconfigArgs builds a misconfiguration scan. It reads configuration
// files rather than a package manifest, so it applies to both target types.
func trivyMisconfigArgs(target string, targetType TargetType, tool ToolSpec,
	server string, ignoreEOL bool) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json", "--scanners", "misconfig"}
	case TargetImage:
		args = []string{"image", "--format", "json", "--scanners", "misconfig"}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}
	if ignoreEOL {
		args = append(args, "--ignore-status", "end_of_life")
	}

	return wrapTrivy(args, target, targetType, tool, server), nil
}

// sbomArgs builds a CycloneDX SBOM generation and returns the host path the
// file will end up at, which is not the path Trivy is given in Docker mode.
func sbomArgs(target string, targetType TargetType, tool ToolSpec,
	server, outputDir string) (toolCmd, string, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, "", err
	}

	name := sbomFileName(target, targetType)

	var hostPath string
	switch {
	case outputDir != "":
		hostPath = filepath.Join(outputDir, name)
	case targetType == TargetDirectory:
		hostPath = filepath.Join(target, name)
	case targetType == TargetImage:
		hostPath = name
	default:
		return toolCmd{}, "", fmt.Errorf("unsupported target type: %s", targetType)
	}

	if tool.Source != ToolSourceDocker {
		args := []string{sbomSubcommand(targetType), "--format", "cyclonedx", "--output", hostPath}
		if server != "" {
			args = append(args, "--server", server)
		}
		return toolCmd{Name: trivyBinary(tool), Args: append(args, target)}, hostPath, nil
	}

	// In Docker mode the output directory has to be writable, so the read-only
	// mount used elsewhere does not apply to it.
	var mounts []string
	var containerOut string
	switch {
	case targetType == TargetDirectory && outputDir != "":
		mounts = []string{"-v", target + ":" + containerScanPath + ":ro", "-v", outputDir + ":" + containerOutputPath}
		containerOut = containerOutputPath + "/" + name
	case targetType == TargetDirectory:
		mounts = []string{"-v", target + ":" + containerScanPath}
		containerOut = containerScanPath + "/" + name
	default:
		if server == "" {
			mounts = append(mounts, "-v", dockerSocketMount)
		}
		mountDir := outputDir
		if mountDir == "" {
			mountDir = "."
		}
		mounts = append(mounts, "-v", mountDir+":"+containerOutputPath)
		containerOut = containerOutputPath + "/" + name
	}

	args := []string{sbomSubcommand(targetType), "--format", "cyclonedx", "--output", containerOut}
	if server != "" {
		args = append(args, "--server", server)
	}
	if targetType == TargetDirectory {
		args = append(args, containerScanPath)
	} else {
		args = append(args, target)
	}

	dockerArgs := append([]string{"run", "--rm"}, mounts...)
	dockerArgs = append(dockerArgs, trivyImage(tool.Image))
	return toolCmd{Name: "docker", Args: append(dockerArgs, args...)}, hostPath, nil
}

func sbomSubcommand(targetType TargetType) string {
	if targetType == TargetImage {
		return "image"
	}
	return "fs"
}

// sbomFileName keeps an image's SBOM identifiable while staying a legal
// filename — a tag reference carries "/" and ":".
func sbomFileName(target string, targetType TargetType) string {
	if targetType == TargetImage {
		return fmt.Sprintf("sbom-%s.json", strings.NewReplacer("/", "_", ":", "_").Replace(target))
	}
	return "sbom-report.json"
}

// wrapTrivy turns tool arguments into the invocation to run: either trivy
// directly, or docker run with the target mounted and the tool arguments
// appended after the image.
func wrapTrivy(args []string, target string, targetType TargetType, tool ToolSpec, server string) toolCmd {
	if tool.Source != ToolSourceDocker {
		return toolCmd{Name: trivyBinary(tool), Args: append(args, target)}
	}

	dockerArgs := []string{"run", "--rm"}
	if targetType == TargetDirectory {
		dockerArgs = append(dockerArgs, "-v", target+":"+containerScanPath+":ro")
		args = append(args, containerScanPath)
	} else {
		if server == "" {
			dockerArgs = append(dockerArgs, "-v", dockerSocketMount)
		}
		args = append(args, target)
	}
	dockerArgs = append(dockerArgs, trivyImage(tool.Image))
	return toolCmd{Name: "docker", Args: append(dockerArgs, args...)}
}

// trivyBinary is what to exec for a binary-source scan: the resolved path when
// detection found one, else the plain name. The fallback keeps the pure arg
// builders usable from tests that never ran detection.
func trivyBinary(tool ToolSpec) string {
	if tool.Binary != "" {
		return tool.Binary
	}
	return "trivy"
}

func gitleaksBinary(tool ToolSpec) string {
	if tool.Binary != "" {
		return tool.Binary
	}
	return "gitleaks"
}

func trivyImage(image string) string {
	if image == "" {
		return DefaultTrivyImage
	}
	return image
}

func gitleaksImage(image string) string {
	if image == "" {
		return DefaultGitleaksImage
	}
	return image
}

