9	// fetchGroupChildren fetches children (subgroups + projects) from GitLab API
10	func (m Model) fetchGroupChildren(client *gitlabclient.Client, parentNode *TreeNode) ([]*TreeNode, error) {
11		groupID := int(parentNode.ID)
12		var currentUserID int64
13		if m.shared.CurrentUser != nil {
14			currentUserID = m.shared.CurrentUser.ID
15		}
16		children := []*TreeNode{}
17	
18		// Fetch direct subgroups only
19		subgroupsOpts := &gitlabclient.ListSubGroupsOptions{
20			ListOptions: gitlabclient.ListOptions{
21				PerPage: 100,
22				Page:    1,
23			},
24		}
25		subgroups, _, err := client.Groups.ListSubGroups(groupID, subgroupsOpts)
26		if err != nil {
27			return nil, err
28		}
29	
30		for _, group := range subgroups {
31			children = append(children, &TreeNode{
32				ID:         group.ID,
33				Name:       group.Name,
34				FullPath:   group.FullPath,
35				Type:       NodeTypeGroup,
36				Parent:     parentNode,
37				Expanded:   false,
38				Visibility: string(group.Visibility),
39				CreatedAt:  group.CreatedAt,
40				WebURL:     group.WebURL,
41			})
42		}
43	
44		// Fetch projects
45		projectsOpts := &gitlabclient.ListGroupProjectsOptions{
46			ListOptions: gitlabclient.ListOptions{
47				PerPage: 100,
