package explorer

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/gitlab"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// handlePullStart handles p key - start pull operation
func (m Model) handlePullStart() (tea.Model, tea.Cmd) {
	node, ok := m.table.Selected()
	if !ok {
		return m, nil
	}

	m.pullTargetNode = node
	return m, func() tea.Msg { return PullSelectionRequestMsg{} }
}

// handlePullDestinationSelected handles workspace directory selection result from app
func (m Model) handlePullDestinationSelected(msg PullDestinationSelectedMsg) (tea.Model, tea.Cmd) {
	m.mode = ModePulling
	m.pullStatus = "Pulling..."

	node := m.pullTargetNode
	targetPath := msg.Path
	client := m.shared.GitLabClient
	cloneMethod := m.config.GitLab.CloneMethod
	gitlabURL := m.config.GitLab.URL

	return m, func() tea.Msg {
		report := m.recursivePull(client, node, targetPath, cloneMethod, gitlabURL)
		return PullCompleteMsg{Report: report}
	}
}

// handlePullComplete handles PullCompleteMsg
func (m Model) handlePullComplete(msg PullCompleteMsg) (tea.Model, tea.Cmd) {
	m.mode = ModeShowingReport
	m.pullTargetNode = nil
	m.pullStatus = ""
	m.reportModal = components.NewReportModal("Pull Complete", msg.Report)
	return m, nil
}

// recursivePull performs a recursive pull/clone operation
func (m Model) recursivePull(client *gitlabclient.Client, node *TreeNode, targetPath, cloneMethod, gitlabURL string) components.PullReport {
	report := components.PullReport{
		Cloned:  []string{},
		Skipped: []string{},
		Errors:  []string{},
	}

	m.recursivePullNode(client, node, targetPath, cloneMethod, gitlabURL, &report)
	return report
}

// recursivePullNode recursively processes a node
func (m Model) recursivePullNode(client *gitlabclient.Client, node *TreeNode, basePath, cloneMethod, gitlabURL string, report *components.PullReport) {
	if node.Type == NodeTypeProject {
		m.pullProject(node, basePath, cloneMethod, gitlabURL, report)
		return
	}

	// It's a group - create directory and process children using slug
	groupPath := filepath.Join(basePath, nodeSlug(node.FullPath))

	// Create directory
	if err := os.MkdirAll(groupPath, 0755); err != nil {
		report.Errors = append(report.Errors, fmt.Sprintf("mkdir %s: %v", groupPath, err))
		return
	}

	// Walk the group. The children stay local: they are discovery nodes, which
	// carry a type and a path and none of the decoration the view renders, so
	// storing them on the tree would blank the role and CI columns for every
	// group a clone passed through. Writing to node.Children from inside a Cmd
	// was also a race against Update, which reads it (Rule 110).
	children := node.Children
	if children == nil {
		fetched, err := discoverGroupChildren(client, node)
		if err != nil {
			report.Errors = append(report.Errors, fmt.Sprintf("fetch %s: %v", node.FullPath, err))
			return
		}
		children = fetched
	}

	// Process children recursively
	for _, child := range children {
		m.recursivePullNode(client, child, groupPath, cloneMethod, gitlabURL, report)
	}
}

// pullProject clones or skips a single project
func (m Model) pullProject(node *TreeNode, basePath, cloneMethod, gitlabURL string, report *components.PullReport) {
	projectPath := filepath.Join(basePath, nodeSlug(node.FullPath))

	// Check if already exists
	if gitlab.DirExists(projectPath) {
		report.Skipped = append(report.Skipped, node.FullPath)
		return
	}

	if err := gitlab.Clone(cloneURL(gitlabURL, cloneMethod, node.FullPath), projectPath); err != nil {
		report.Errors = append(report.Errors, fmt.Sprintf("clone %s: %v", node.FullPath, err))
		return
	}

	report.Cloned = append(report.Cloned, node.FullPath)
}

// cloneURL builds the git URL for a project from the configured GitLab URL and
// the clone method. SSH form takes the host alone, so the scheme is stripped.
func cloneURL(gitlabURL, cloneMethod, fullPath string) string {
	cleanURL := strings.TrimSuffix(gitlabURL, "/")
	if cloneMethod != "ssh" {
		return fmt.Sprintf("%s/%s.git", cleanURL, fullPath)
	}

	host := strings.TrimPrefix(cleanURL, "https://")
	host = strings.TrimPrefix(host, "http://")
	return fmt.Sprintf("git@%s:%s.git", host, fullPath)
}

package explorer

import (
	"testing"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The selection is roots plus exclusions rather than a list of repositories,
// so these tests are all about what it can answer *without* having discovered
// anything. Every path below names a node that was never fetched.

func TestTickingAGroupTakesEverythingUnderIt(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")

	for _, path := range []string{
		"acme/platform",
		"acme/platform/backend",
		"acme/platform/tools/ci",
	} {
		if !s.includes(path) {
			t.Errorf("%q is not included, but its group was ticked", path)
		}
	}
	if s.includes("acme/other") {
		t.Error("a sibling of the ticked group was included")
	}
	if s.includes("acme") {
		t.Error("the parent of the ticked group was included")
	}
}

// The trailing separator is the whole of it: a prefix match alone makes
// "acme/platform-tools" a child of "acme/platform".
func TestASiblingSharingANamePrefixIsNotADescendant(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")

	if s.includes("acme/platform-tools") {
		t.Error("acme/platform-tools was included by acme/platform")
	}
	if got := s.state("acme/platform"); got != theme.CheckAll {
		t.Errorf("state = %v, want CheckAll", got)
	}
}

func TestDrillingInAndUntickingCutsOneSubtree(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")
	s.toggle("acme/platform/legacy")

	if s.includes("acme/platform/legacy") {
		t.Error("the unticked subgroup is still included")
	}
	if s.includes("acme/platform/legacy/old-api") {
		t.Error("a child of the unticked subgroup is still included")
	}
	if !s.includes("acme/platform/backend") {
		t.Error("unticking one subgroup took its siblings with it")
	}
}

// Re-ticking below an exclusion turns that branch back on, which is what makes
// the control reversible at any depth rather than only at the level it was used.
func TestReTickingUnderAnExclusionTurnsItBackOn(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")
	s.toggle("acme/platform/legacy")
	s.toggle("acme/platform/legacy/keep-me")

	if !s.includes("acme/platform/legacy/keep-me") {
		t.Error("the re-ticked node is not included")
	}
	if !s.includes("acme/platform/legacy/keep-me/deeper") {
		t.Error("the re-ticked node does not carry its own children")
	}
	if s.includes("acme/platform/legacy/drop-me") {
		t.Error("re-ticking one child re-included its siblings")
	}
}

func TestTickingTwiceIsUnticking(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")
	s.toggle("acme/platform")

	if s.includes("acme/platform") {
		t.Error("ticking twice left the node selected")
	}
	if !s.isEmpty() {
		t.Error("the selection is not empty after the only root was unticked")
	}
}

// A single project is a root like any other (decision 8), and carries nothing
// below it.
func TestAProjectCanBeSelectedOnItsOwn(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform/backend")

	if !s.includes("acme/platform/backend") {
		t.Error("the project was not selected")
	}
	if s.includes("acme/platform/frontend") {
		t.Error("selecting one project took a sibling with it")
	}
	if got := s.state("acme/platform"); got != theme.CheckSome {
		t.Errorf("the parent group shows %v, want CheckSome — one child is on", got)
	}
}

func TestTheCheckboxStatesCoverTheThreeCases(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")
	s.toggle("acme/platform/legacy")

	tests := map[string]theme.CheckState{
		// Everything under it is on.
		"acme/platform/backend": theme.CheckAll,
		// On, but something below is off.
		"acme/platform": theme.CheckSome,
		// Off itself, but something below is on.
		"acme": theme.CheckSome,
		// Off, with nothing on below.
		"acme/platform/legacy":     theme.CheckNone,
		"acme/platform/legacy/old": theme.CheckNone,
		"other":                    theme.CheckNone,
	}

	for path, want := range tests {
		if got := s.state(path); got != want {
			t.Errorf("state(%q) = %v, want %v", path, got, want)
		}
	}
}

// The confirmation screen states this, because the repository count cannot be
// known until discovery has run (decision 7).
func TestTheCountsAreRootsAndExclusions(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")
	s.toggle("other/tools")
	s.toggle("acme/platform/legacy")

	roots, exclusions := s.counts()
	if roots != 2 || exclusions != 1 {
		t.Errorf("counts() = (%d, %d), want (2, 1)", roots, exclusions)
	}
	if len(s.rootPaths()) != 2 {
		t.Errorf("rootPaths() = %v, want the two roots", s.rootPaths())
	}
}

// Unticking a root removes it rather than leaving it behind an exclusion that
// says the same thing — two ways to express one state is how a display starts
// disagreeing with itself.
func TestUntickingARootDropsItRatherThanMaskingIt(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme/platform")
	s.toggle("acme/platform")

	if s.roots["acme/platform"] {
		t.Error("the root is still there, masked by an exclusion")
	}
	if got := s.state("acme/platform"); got != theme.CheckNone {
		t.Errorf("state = %v, want CheckNone", got)
	}
}

// A top-level group has no parent, so the walk up has to stop rather than
// looping on an empty string.
func TestATopLevelPathTerminates(t *testing.T) {
	s := newCloneSelection()
	s.toggle("acme")

	if !s.includes("acme/anything") {
		t.Error("a top-level root does not include its children")
	}
	if s.includes("elsewhere") {
		t.Error("a top-level root included an unrelated top-level path")
	}
}

package explorer

import (
	"strings"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// cloneSelection is what the user has picked to clone: a set of **roots**, plus
// the descendants explicitly taken back out (§3.16, decision 11).
//
// It is deliberately not a list of the chosen repositories. Building one would
// mean enumerating a group's children the moment it is ticked — the whole API
// walk, run before the user has confirmed anything — which is the freeze the
// pipelined design exists to remove, moved one screen earlier. "This group,
// minus these" needs to know nothing about what the group contains, so a group
// nobody has expanded can still be selected, displayed and walked.
//
// Paths are `FullPath` throughout: "acme/platform/backend". That is the forge's
// own hierarchy, and by decision 4 it is the directory layout as well, so one
// string serves for membership, display and destination.
type cloneSelection struct {
	roots    map[string]bool
	excluded map[string]bool
}

func newCloneSelection() cloneSelection {
	return cloneSelection{roots: map[string]bool{}, excluded: map[string]bool{}}
}

// includes reports whether a path is part of the selection.
//
// The answer is the **nearest** marked ancestor-or-self: a root includes
// everything below it, an exclusion cuts everything below itself, and a root
// added under an exclusion turns it back on. Nothing marked anywhere above
// means the path was never chosen.
func (s cloneSelection) includes(path string) bool {
	for p := path; p != ""; p = parentPath(p) {
		if s.excluded[p] {
			return false
		}
		if s.roots[p] {
			return true
		}
	}
	return false
}

// toggle flips one node, which is the only way either set is written to.
//
// Excluding something that was never included, or rooting something already
// covered, would both be noise the display could not explain, so each side
// clears the other.
func (s cloneSelection) toggle(path string) {
	if s.includes(path) {
		delete(s.roots, path)
		s.excluded[path] = true
		return
	}
	delete(s.excluded, path)
	s.roots[path] = true
}

// state is what the checkbox shows.
//
// It needs no discovery, which is the point: an exclusion only ever comes from
// a keystroke on a node already on screen, so "is something below this off"
// is answerable from the two sets alone — including for a group whose children
// have never been fetched.
func (s cloneSelection) state(path string) theme.CheckState {
	if s.includes(path) {
		if hasDescendant(s.excluded, path) {
			return theme.CheckSome
		}
		return theme.CheckAll
	}
	if hasDescendant(s.roots, path) {
		return theme.CheckSome
	}
	return theme.CheckNone
}

// isEmpty reports whether anything at all is selected.
func (s cloneSelection) isEmpty() bool { return len(s.roots) == 0 }

// counts is what the header states instead of a repository count: the number
// cannot be known before discovery has run, and discovery only starts once the
// user has confirmed (decision 7).
func (s cloneSelection) counts() (roots, exclusions int) {
	return len(s.roots), len(s.excluded)
}

// rootPaths returns the selected roots, for the walk to start from.
func (s cloneSelection) rootPaths() []string {
	out := make([]string, 0, len(s.roots))
	for p := range s.roots {
		out = append(out, p)
	}
	return out
}

// parentPath drops the last segment, returning "" at the top.
func parentPath(path string) string {
	if i := strings.LastIndex(path, "/"); i > 0 {
		return path[:i]
	}
	return ""
}

// hasDescendant reports whether the set holds anything strictly below path.
// The trailing separator is what keeps "acme/platform-tools" from counting as a
// descendant of "acme/platform".
func hasDescendant(set map[string]bool, path string) bool {
	prefix := path + "/"
	for p := range set {
		if strings.HasPrefix(p, prefix) {
			return true
		}
	}
	return false
}

package explorer

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/shared"
)

// The recursive pull is run for real against a throwaway git repository and a
// temporary directory: it is what proves the directory tree mirrors the group
// tree and that an existing checkout is skipped rather than clobbered. Only the
// clone URL is synthetic — the "GitLab host" is a local path.

func requireGit(t *testing.T) {
	t.Helper()
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not found in PATH")
	}
}

// seedRemote creates a git repository that can be cloned from, at
// <root>/<fullPath>.git — the layout pullProject builds its HTTPS URL for.
func seedRemote(t *testing.T, root, fullPath string) {
	t.Helper()
	dir := filepath.Join(root, fullPath+".git")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("creating the remote: %v", err)
	}

	run := func(args ...string) {
		t.Helper()
		cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}

	run("init", "--initial-branch=main")
	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# seed\n"), 0o600); err != nil {
		t.Fatalf("writing README: %v", err)
	}
	run("add", "README.md")
	run("-c", "user.name=devdesk", "-c", "user.email=devdesk@example.com",
		"-c", "commit.gpgsign=false", "commit", "-m", "seed")
}

// pullModel returns a model whose configured GitLab "URL" is a local directory,
// so the clone URLs it builds resolve to the seeded remotes.
func pullModel(t *testing.T, remoteRoot string) Model {
	t.Helper()
	cfg := testConfig()
	cfg.GitLab.URL = remoteRoot
	return New(cfg, &shared.State{})
}

// ── Projects ─────────────────────────────────────────────────────────────────

func TestPullClonesAProject(t *testing.T) {
	requireGit(t)
	remotes := t.TempDir()
	seedRemote(t, remotes, "api")
	target := t.TempDir()
	m := pullModel(t, remotes)

	report := m.recursivePull(nil, &TreeNode{Name: "API", FullPath: "api", Type: NodeTypeProject},
		target, "https", remotes)

	if len(report.Errors) != 0 {
		t.Fatalf("pull reported errors: %v", report.Errors)
	}
	if len(report.Cloned) != 1 || report.Cloned[0] != "api" {
		t.Errorf("Cloned = %v, want the one project", report.Cloned)
	}
	if _, err := os.Stat(filepath.Join(target, "api", "README.md")); err != nil {
		t.Errorf("the clone is missing its contents: %v", err)
	}
}

// A checkout that already exists is left alone: overwriting it would discard
// whatever the user has in progress.
func TestPullSkipsAnExistingCheckout(t *testing.T) {
	target := t.TempDir()
	if err := os.MkdirAll(filepath.Join(target, "api"), 0o755); err != nil {
		t.Fatalf("seeding the destination: %v", err)
	}
	m := pullModel(t, t.TempDir())

	report := m.recursivePull(nil, &TreeNode{Name: "API", FullPath: "api", Type: NodeTypeProject},
		target, "https", "https://gl.example.com")

	if len(report.Skipped) != 1 || report.Skipped[0] != "api" {
		t.Errorf("Skipped = %v, want the existing checkout", report.Skipped)
	}
	if len(report.Cloned) != 0 {
		t.Errorf("Cloned = %v, want nothing re-cloned", report.Cloned)
	}
}

func TestPullReportsACloneFailure(t *testing.T) {
	requireGit(t)
	m := pullModel(t, t.TempDir())

	report := m.recursivePull(nil, &TreeNode{Name: "API", FullPath: "nope", Type: NodeTypeProject},
		t.TempDir(), "https", filepath.Join(t.TempDir(), "missing"))

	if len(report.Errors) != 1 {
		t.Fatalf("Errors = %v, want the failed clone", report.Errors)
	}
	if !strings.Contains(report.Errors[0], "nope") {
		t.Errorf("the error does not name the project: %q", report.Errors[0])
	}
}

// The clone method decides the URL shape. SSH takes the host alone, so the
// scheme has to come off, and a trailing slash on the configured URL must not
// produce a double slash in the HTTPS form.
func TestCloneURL(t *testing.T) {
	tests := []struct {
		name      string
		gitlabURL string
		method    string
		want      string
	}{
		{"https", "https://gl.example.com", "https", "https://gl.example.com/infra/api.git"},
		{"https with a trailing slash", "https://gl.example.com/", "https", "https://gl.example.com/infra/api.git"},
		{"an unset method defaults to https", "https://gl.example.com", "", "https://gl.example.com/infra/api.git"},
		{"ssh", "https://gl.example.com", "ssh", "git@gl.example.com:infra/api.git"},
		{"ssh over plain http", "http://gl.example.com/", "ssh", "git@gl.example.com:infra/api.git"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := cloneURL(tt.gitlabURL, tt.method, "infra/api"); got != tt.want {
				t.Errorf("cloneURL() = %q, want %q", got, tt.want)
			}
		})
	}
}

// ── Groups ───────────────────────────────────────────────────────────────────

// Pulling a group mirrors the tree on disk, one directory per level, with the
// slug rather than the full path as the directory name.
func TestPullMirrorsTheGroupTree(t *testing.T) {
	requireGit(t)
	remotes := t.TempDir()
	seedRemote(t, remotes, "infra/api")
	seedRemote(t, remotes, "infra/tools/cli")
	target := t.TempDir()
	m := pullModel(t, remotes)

	tools := &TreeNode{Name: "Tools", FullPath: "infra/tools", Type: NodeTypeGroup}
	tools.Children = []*TreeNode{{Name: "CLI", FullPath: "infra/tools/cli", Type: NodeTypeProject, Parent: tools}}
	infra := &TreeNode{Name: "Infra", FullPath: "infra", Type: NodeTypeGroup}
	infra.Children = []*TreeNode{
		{Name: "API", FullPath: "infra/api", Type: NodeTypeProject, Parent: infra},
		tools,
	}

	report := m.recursivePull(nil, infra, target, "https", remotes)

	if len(report.Errors) != 0 {
		t.Fatalf("pull reported errors: %v", report.Errors)
	}
	if len(report.Cloned) != 2 {
		t.Errorf("Cloned = %v, want both projects", report.Cloned)
	}
	for _, want := range []string{"infra/api", "infra/tools/cli"} {
		if _, err := os.Stat(filepath.Join(target, filepath.FromSlash(want), "README.md")); err != nil {
			t.Errorf("%s was not cloned into place: %v", want, err)
		}
	}
}

// A group whose children have not been browsed yet is fetched during the pull,
// so pulling the root does not require walking the tree by hand first.
func TestPullFetchesUnloadedChildren(t *testing.T) {
	requireGit(t)
	remotes := t.TempDir()
	seedRemote(t, remotes, "infra/api")

	f := newFakeGitLab(t, map[string]string{
		"/api/v4/groups/1/subgroups": `[]`,
		"/api/v4/groups/1/projects":  `[{"id":11,"name":"API","path_with_namespace":"infra/api"}]`,
		"/api/v4/projects/11":        `[]`,
	})
	m := serverModel(t, f)
	m.config.GitLab.URL = remotes
	target := t.TempDir()

	node := &TreeNode{ID: 1, Name: "Infra", FullPath: "infra", Type: NodeTypeGroup} // Children nil
	report := m.recursivePull(m.shared.GitLabClient, node, target, "https", remotes)

	if len(report.Errors) != 0 {
		t.Fatalf("pull reported errors: %v", report.Errors)
	}
	if len(report.Cloned) != 1 {
		t.Errorf("Cloned = %v, want the project fetched during the pull", report.Cloned)
	}
	// And they stay off the tree. Discovery nodes carry a path and a type and
	// none of the decoration the view renders, so caching them here blanked the
	// role and CI columns for every group a clone walked through — and the write
	// happened inside a Cmd, racing the Update that reads it (Rule 110).
	if node.Children != nil {
		t.Error("discovery nodes were stored on the tree the view renders")
	}
}

func TestPullReportsAFetchFailure(t *testing.T) {
	m := serverModel(t, newFakeGitLab(t, nil)) // everything 404s

	report := m.recursivePull(m.shared.GitLabClient,
		&TreeNode{ID: 1, FullPath: "infra", Type: NodeTypeGroup}, t.TempDir(), "https", "https://gl")

	if len(report.Errors) != 1 || !strings.Contains(report.Errors[0], "fetch infra") {
		t.Errorf("Errors = %v, want the failed fetch", report.Errors)
	}
}

// A directory that cannot be created stops that branch and is reported rather
// than crashing the pull.
func TestPullReportsAMkdirFailure(t *testing.T) {
	target := t.TempDir()
	blocker := filepath.Join(target, "infra")
	if err := os.WriteFile(blocker, []byte("not a directory"), 0o600); err != nil {
		t.Fatalf("seeding the blocker: %v", err)
	}
	m := pullModel(t, t.TempDir())

	report := m.recursivePull(nil, &TreeNode{FullPath: "infra", Type: NodeTypeGroup}, target, "https", "https://gl")

	if len(report.Errors) != 1 || !strings.Contains(report.Errors[0], "mkdir") {
		t.Errorf("Errors = %v, want the failed mkdir", report.Errors)
	}
}

// An empty report is still a report: the modal says "nothing to do" rather than
// rendering nil slices.
func TestPullReportStartsEmptyNotNil(t *testing.T) {
	m := pullModel(t, t.TempDir())

	report := m.recursivePull(nil, &TreeNode{FullPath: "empty", Type: NodeTypeGroup,
		Children: []*TreeNode{}}, t.TempDir(), "https", "https://gl")

	if report.Cloned == nil || report.Skipped == nil || report.Errors == nil {
		t.Errorf("report holds nil slices: %+v", report)
	}
}

package explorer

import (
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	tea "github.com/charmbracelet/bubbletea"
)

// perPage is what every list endpoint asks for. GitLab caps it at 100.
const perPage = 100

// listAll walks every page of a list endpoint and returns the lot (D34).
//
// Each caller used to pass `Page: 1` and keep only what came back, so a group
// with more than perPage subgroups or projects was silently cut: the explorer
// showed fewer than it had and a recursive clone skipped repositories without
// saying so. The loop lives here rather than at each of the four call sites
// because four copies of it is how one of them would end up wrong.
//
// opts is the caller's embedded ListOptions, mutated between calls, so the
// fetch closure sees the new page without the caller rebuilding its options.
func listAll[T any](opts *gitlabclient.ListOptions, fetch func() ([]T, *gitlabclient.Response, error)) ([]T, error) {
	opts.PerPage = perPage
	opts.Page = 1

	var all []T
	for {
		page, resp, err := fetch()
		if err != nil {
			return nil, err
		}
		all = append(all, page...)

		// NextPage is 0 on the last page. Comparing against the page just
		// fetched rather than against 0 alone also stops a server that keeps
		// pointing back at it, which would otherwise spin for ever — and it is
		// a bound that cannot cut a legitimate response short, which a page
		// limit would be.
		if resp == nil || resp.NextPage <= opts.Page {
			return all, nil
		}
		opts.Page = resp.NextPage
	}
}

// listGroupChildren lists a group's direct subgroups and its projects, every
// page of each, and decorates nothing.
//
// It is the half the two callers share. What they do *not* share is the
// decoration: the explorer wants a role and a CI status per row, and a clone
// wants a path. Keeping the listing here and the decoration at each caller is
// what lets the clone stop paying for two extra requests per project.
func listGroupChildren(client *gitlabclient.Client, groupID int) ([]*gitlabclient.Group, []*gitlabclient.Project, error) {
	subgroupsOpts := &gitlabclient.ListSubGroupsOptions{}
	subgroups, err := listAll(&subgroupsOpts.ListOptions, func() ([]*gitlabclient.Group, *gitlabclient.Response, error) {
		return client.Groups.ListSubGroups(groupID, subgroupsOpts)
	})
	if err != nil {
		return nil, nil, err
	}

	projectsOpts := &gitlabclient.ListGroupProjectsOptions{}
	projects, err := listAll(&projectsOpts.ListOptions, func() ([]*gitlabclient.Project, *gitlabclient.Response, error) {
		return client.Groups.ListGroupProjects(groupID, projectsOpts)
	})
	if err != nil {
		return nil, nil, err
	}

	return subgroups, projects, nil
}

// discoverGroupChildren walks a group for the recursive clone: the nodes it
// returns carry a type and a path, which is all a clone reads.
//
// It deliberately skips the per-project pipeline status and access level that
// the explorer's own load fetches. Those are two extra requests per project —
// on two hundred repositories, 400 calls for a CI badge and a role that no
// clone ever looks at.
//
// The nodes are therefore **not** interchangeable with the ones the explorer
// browses, and must not be stored on the tree the view renders: the role and CI
// columns would go blank for every group a clone had walked through.
func discoverGroupChildren(client *gitlabclient.Client, parentNode *TreeNode) ([]*TreeNode, error) {
	subgroups, projects, err := listGroupChildren(client, int(parentNode.ID))
	if err != nil {
		return nil, err
	}

	children := make([]*TreeNode, 0, len(subgroups)+len(projects))
	for _, group := range subgroups {
		children = append(children, &TreeNode{
			ID:       group.ID,
			Name:     group.Name,
			FullPath: group.FullPath,
			Type:     NodeTypeGroup,
			Parent:   parentNode,
		})
	}
	for _, project := range projects {
		children = append(children, projectToTreeNode(project, parentNode, "", 0))
	}
	return children, nil
}

// loadRootGroups charge les groupes racine
func (m Model) loadRootGroups() tea.Cmd {
	client := m.shared.GitLabClient
	var currentUserID int64
	if m.shared.CurrentUser != nil {
		currentUserID = m.shared.CurrentUser.ID
	}

	return func() tea.Msg {
		// Récupérer les groupes racine (top-level groups)
		opts := &gitlabclient.ListGroupsOptions{
			TopLevelOnly: gitlabclient.Ptr(true),
		}

		groups, err := listAll(&opts.ListOptions, func() ([]*gitlabclient.Group, *gitlabclient.Response, error) {
			return client.Groups.ListGroups(opts)
		})
		if err != nil {
			return LoadErrorMsg{Error: err}
		}

		// Convertir en TreeNodes
		nodes := make([]*TreeNode, len(groups))
		for i, group := range groups {
			nodes[i] = &TreeNode{
				ID:          group.ID,
				Name:        group.Name,
				FullPath:    group.FullPath,
				Type:        NodeTypeGroup,
				Children:    nil, // Lazy load
				Expanded:    false,
				Visibility:  string(group.Visibility),
				CreatedAt:   group.CreatedAt,
				AccessLevel: fetchGroupAccessLevel(client, group.ID, currentUserID),
				WebURL:      group.WebURL,
			}
		}

		return RootGroupsLoadedMsg{Nodes: nodes}
	}
}

// loadChildren charge les sous-groupes et projets d'un groupe
func (m Model) loadChildren(parentNode *TreeNode) tea.Cmd {
	client := m.shared.GitLabClient
	groupID := int(parentNode.ID)
	var currentUserID int64
	if m.shared.CurrentUser != nil {
		currentUserID = m.shared.CurrentUser.ID
	}

	return func() tea.Msg {
		children := []*TreeNode{}

		// Charger les sous-groupes directs (pas les descendants) et les projets
		subgroups, projects, err := listGroupChildren(client, groupID)
		if err != nil {
			return LoadErrorMsg{Error: err, ParentNode: parentNode}
		}

		for _, group := range subgroups {
			children = append(children, &TreeNode{
				ID:          group.ID,
				Name:        group.Name,
				FullPath:    group.FullPath,
				Type:        NodeTypeGroup,
				Parent:      parentNode,
				Expanded:    false,
				Visibility:  string(group.Visibility),
				CreatedAt:   group.CreatedAt,
				AccessLevel: fetchGroupAccessLevel(client, group.ID, currentUserID),
				WebURL:      group.WebURL,
			})
		}

		// Décorer les projets : rôle et statut CI, que la vue affiche en colonnes
		for _, project := range projects {
			ciStatus := fetchLastPipelineStatus(client, project.ID)
			accessLevel := fetchProjectAccessLevel(client, int64(project.ID), currentUserID)
			children = append(children, projectToTreeNode(project, parentNode, ciStatus, accessLevel))
		}

		return ChildrenLoadedMsg{
			ParentNode: parentNode,
			Children:   children,
		}
	}
}

// projectToTreeNode converts a GitLab project to a TreeNode with metadata
func projectToTreeNode(project *gitlabclient.Project, parent *TreeNode, pipelineStatus string, accessLevel int) *TreeNode {
	return &TreeNode{
		ID:                int64(project.ID),
		Name:              project.Name,
		FullPath:          project.PathWithNamespace,
		Type:              NodeTypeProject,
		Parent:            parent,
		Expanded:          false,
		Visibility:        string(project.Visibility),
		CreatedAt:         project.CreatedAt,
		LastActivityAt:    project.LastActivityAt,
		PipelineStatus:    pipelineStatus,
		AccessLevel:       accessLevel,
		MarkedForDeletion: project.MarkedForDeletionOn != nil,
		WebURL:            project.WebURL,
	}
}

// fetchLastPipelineStatus fetches the latest pipeline status for a project
func fetchLastPipelineStatus(client *gitlabclient.Client, projectID int64) string {
	pipelines, _, err := client.Pipelines.ListProjectPipelines(projectID, &gitlabclient.ListProjectPipelinesOptions{
		ListOptions: gitlabclient.ListOptions{PerPage: 1, Page: 1},
	})
	if err != nil || len(pipelines) == 0 {
		return ""
	}
	return pipelines[0].Status
}

// fetchGroupAccessLevel returns the current user's access level in a group (0 if unknown)
func fetchGroupAccessLevel(client *gitlabclient.Client, groupID int64, userID int64) int {
	if userID == 0 {
		return 0
	}
	member, _, err := client.GroupMembers.GetInheritedGroupMember(int(groupID), userID)
	if err != nil {
		return 0
	}
	return int(member.AccessLevel)
}

// fetchProjectAccessLevel returns the current user's access level in a project (0 if unknown)
func fetchProjectAccessLevel(client *gitlabclient.Client, projectID int64, userID int64) int {
	if userID == 0 {
		return 0
	}
	member, _, err := client.ProjectMembers.GetInheritedProjectMember(int(projectID), userID)
	if err != nil {
		return 0
	}
	return int(member.AccessLevel)
}

package explorer

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/oci"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ViewMode represents the current mode of the view
type ViewMode int

const (
	ModeNormal ViewMode = iota
	ModePulling
	ModeShowingReport
	ModeLoadingTemplates
	ModeCreatingProject
	ModeConfirmingDelete
)

// Model représente le modèle de la vue GitLab Explorer
type Model struct {
	config *config.Config
	shared *shared.State
	width  int
	height int

	// Table
	table   datatable.Model[*TreeNode]
	spinner spinner.Model

	// Tree state
	nodes         []*TreeNode
	loading       bool
	firstLoadDone bool // true after the first load attempt completes (success or error)
	error         string

	// Drill-down navigation
	currentGroupNode *TreeNode   // nil = root level
	navigationStack  []*TreeNode // Stack of parent groups for backspace navigation
	cursorStack      []int       // Cursor positions per level for restoration on drill-up

	// Pull mode state
	mode           ViewMode
	reportModal    *components.ReportModal
	pullTargetNode *TreeNode
	pullStatus     string

	// Creation mode state
	creationForm       *components.CreationForm
	creationParentName string              // Parent stashed during template loading
	creationParentID   int64               // Parent ID stashed during template loading
	templateEntries    []oci.TemplateEntry // Loaded template entries for repo+tag resolution

	// Tab navigation
	activeTabIndex int // Focused tab index (last tab = current level)

	// Delete mode state
	deleteConfirmModal *components.DeleteConfirmModal
	deleteTargetNode   *TreeNode
	footerError        string // transient action error shown in footer (Rule 128)

	// Path to select after refresh (for newly created items)
	pendingSelectPath string
}

// New crée une nouvelle instance du modèle explorer
func New(cfg *config.Config, sharedState *shared.State) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	return Model{
		config:  cfg,
		shared:  sharedState,
		nodes:   []*TreeNode{},
		loading: false,
		mode:    ModeNormal,
		table: datatable.New(datatable.Config[*TreeNode]{
			Columns:    explorerColumns(),
			SortColumn: columnType,
		}),
		spinner: s,
	}
}

// Init initialise le modèle
func (m Model) Init() tea.Cmd {
	// Charger les groupes racine au démarrage
	if m.shared.GitLabClient != nil {
		m.loading = true
		return tea.Batch(m.spinner.Tick, m.loadRootGroups())
	}
	return nil
}

// InEditMode returns true if the view is in an edit mode or filter search
func (m Model) InEditMode() bool {
	return m.creationForm != nil || m.mode != ModeNormal || m.table.InEditMode()
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	if !m.table.FilterBar().IsVisible() || m.loading || m.error != "" || len(m.nodes) == 0 {
		return false
	}
	switch m.mode {
	case ModePulling, ModeLoadingTemplates, ModeCreatingProject, ModeConfirmingDelete, ModeShowingReport:
		return false
	}
	return m.creationForm == nil
}

// tabCount returns the total number of tabs (home + navigation stack + current group)
func (m Model) tabCount() int {
	count := 1 // home tab
	for _, node := range m.navigationStack {
		if node != nil {
			count++
		}
	}
	if m.currentGroupNode != nil {
		count++
	}
	return count
}

// resize adjusts table dimensions based on terminal size
func (m *Model) resize(width, height int) {
	// Rule 124: the footer (tab bar + filter bar) is outside the viewport, so
	// only the table's own header row is subtracted. The Rule 116 arithmetic is
	// the component's — seven ratios and a remainder used to live here.
	m.table.Resize(width, max(height-1, 1))
}

package explorer

import (
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/ui/datatable"
)

// numColumns is the number of columns in the explorer table
const numColumns = 8

// Column minimum widths. The table used to size every column as a ratio of the
// available space, which reads as deliberate but is not: at 80 columns Type got
// 5 and Created got 8, neither wide enough for its own header. Floors plus a
// flexible Name and Slug say what actually matters when space is short.
const (
	colTypeMin       = 10
	colNameMin       = 20
	colSlugMin       = 16
	colVisibilityMin = 12
	colRoleMin       = 12
	colCreatedMin    = 12
	colActivityMin   = 12
	colCIMin         = 6
)

// columnName is the column the explorer opens sorted by.
const columnType = 0

// explorerColumns describes the explorer table. Slug, Role and CI do not sort:
// a slug orders the same as the name beside it, and neither a role nor a
// pipeline icon has an order anyone would recognise.
func explorerColumns() []datatable.Column[*TreeNode] {
	return []datatable.Column[*TreeNode]{
		{
			Title: "Type", MinWidth: colTypeMin,
			Cell: nodeTypeLabel,
			Less: func(a, b *TreeNode) bool { return string(a.Type) < string(b.Type) },
		},
		{
			Title: "Name", MinWidth: colNameMin, Flex: 2,
			Cell:   func(n *TreeNode) string { return n.Name },
			Less:   func(a, b *TreeNode) bool { return strings.ToLower(a.Name) < strings.ToLower(b.Name) },
			Search: func(n *TreeNode) string { return n.Name },
		},
		{
			Title: "Slug", MinWidth: colSlugMin, Flex: 1,
			Cell: func(n *TreeNode) string { return nodeSlug(n.FullPath) },
			// The whole path, not the slug shown: a query naming a parent group
			// has always matched, and the slug is a suffix of it anyway.
			Search: func(n *TreeNode) string { return n.FullPath },
		},
		{
			Title: "Visibility", MinWidth: colVisibilityMin,
			Cell: visibilityLabel,
			Less: func(a, b *TreeNode) bool { return strings.ToLower(a.Visibility) < strings.ToLower(b.Visibility) },
		},
		{
			Title: "Role", MinWidth: colRoleMin,
			Cell: func(n *TreeNode) string { return n.AccessLevelName() },
		},
		{
			Title: "Created", MinWidth: colCreatedMin,
			Cell: func(n *TreeNode) string { return timeAgo(n.CreatedAt) },
			Less: func(a, b *TreeNode) bool { return timeBefore(a.CreatedAt, b.CreatedAt) },
		},
		{
			Title: "Activity", MinWidth: colActivityMin,
			Cell: func(n *TreeNode) string { return timeAgo(n.LastActivityAt) },
			Less: func(a, b *TreeNode) bool { return timeBefore(a.LastActivityAt, b.LastActivityAt) },
		},
		{
			Title: "CI", MinWidth: colCIMin,
			Cell: pipelineStatusLabel,
		},
	}
}

// timeBefore compares two nullable times (nil is considered "oldest")
func timeBefore(a, b *time.Time) bool {
	if a == nil && b == nil {
		return false
	}
	if a == nil {
		return true
	}
	if b == nil {
		return false
	}
	return a.Before(*b)
}

package explorer

import (
	"strings"
	"time"
)

// NodeType représente le type de nœud dans l'arbre
type NodeType string

const (
	NodeTypeGroup   NodeType = "group"
	NodeTypeProject NodeType = "project"
)

// TreeNode représente un nœud dans l'arbre GitLab
type TreeNode struct {
	ID       int64 // GitLab uses int64 for IDs
	Name     string
	FullPath string
	Type     NodeType
	Children []*TreeNode
	Expanded bool
	Loading  bool // True when loading children
	Parent   *TreeNode
	Depth    int // Depth in tree (for rendering)

	// Metadata for flat table display
	Visibility        string     // "private", "internal", "public"
	AccessLevel       int        // User's access level (0=none, 10=guest, 20=reporter, 30=dev, 40=maintainer, 50=owner)
	CreatedAt         *time.Time // Creation date
	LastActivityAt    *time.Time // Last activity date
	PipelineStatus    string     // Last pipeline status ("success", "failed", "running", "pending", etc.)
	MarkedForDeletion bool       // True if the project is already scheduled for deletion
	WebURL            string     // Full HTTPS URL for opening in browser
}

// IsExpandable retourne vrai si le nœud peut être étendu
func (n *TreeNode) IsExpandable() bool {
	return n.Type == NodeTypeGroup
}

// Toggle expande ou contracte le nœud
func (n *TreeNode) Toggle() {
	if n.IsExpandable() {
		n.Expanded = !n.Expanded
	}
}

// AccessLevelName returns a human-readable role name for the access level
func (n *TreeNode) AccessLevelName() string {
	switch {
	case n.AccessLevel >= 50:
		return "Owner"
	case n.AccessLevel >= 40:
		return "Maintainer"
	case n.AccessLevel >= 30:
		return "Developer"
	case n.AccessLevel >= 20:
		return "Reporter"
	case n.AccessLevel >= 10:
		return "Guest"
	default:
		return ""
	}
}

// nodeSlug returns the last path segment of a GitLab FullPath (the URL slug)
func nodeSlug(fullPath string) string {
	parts := strings.Split(fullPath, "/")
	return parts[len(parts)-1]
}

