139		// nothing. Naming the failures now is the only record there will be.
140		if failed := m.clone.failures(); len(failed) > 0 {
141			m.footerError = failureSummary(failed)
142			return m, clearFooterMsgCmd()
143		}
144		return m, nil
145	}
146	
147	// failureSummary names one failure and counts the rest — the footer is one line.
148	func failureSummary(failed []string) string {
149		if len(failed) == 1 {
150			return "Failed to clone " + failed[0] + " — check logs"
151		}
152		return "Failed to clone " + failed[0] + " and " +
153			plural(len(failed)-1, "other") + " — check logs"
154	}
155	
156	func plural(n int, word string) string {
157		if n == 1 {
158			return "1 " + word
159		}
160		return strconv.Itoa(n) + " " + word + "s"
161	}
162	
163	// handleCloneEsc cancels a running pipeline, or closes a finished one.
164	//
165	// The two are one key because they are one intent — "I am done with this" — and
166	// separating them would need the user to know which state the list is in. A
167	// second press while cancelling does nothing: forcing would mean killing a
168	// `git clone` mid-write, which is the half-repository decision 12 rules out.
169	func (m Model) handleCloneEsc() (tea.Model, tea.Cmd) {
170		if m.clone == nil {
171			m.mode = ModeNormal
172			return m, nil
173		}
174		if m.clone.finished {
175			return m.handleCloneClose()
176		}
177		if m.clone.cancelling {
178			return m, nil
179		}
180	
181		m.clone.cancelling = true
182		m.clone.run.cancel()
183		return m, nil
184	}
185	
186	// handleCloneClose discards the list and returns to the tree.
187	func (m Model) handleCloneClose() (tea.Model, tea.Cmd) {
188		m.clone = nil
189		m.selection = newCloneSelection()
190		m.selectionNodes = nil
191		m.mode = ModeNormal
192		m.updateTableRows()
193		return m, nil
194	}
195	
196	// cloneStatusLine is what the view puts under the list: what the run is doing,
197	// then what it did.
198	func (m Model) cloneStatusLine() string {
199		if m.clone == nil {
200			return ""
201		}
202		found, cloned, present, failed := m.clone.counts()
203	
204		var b strings.Builder
205		switch {
206		case m.clone.finished:
207			b.WriteString("Done — ")
208		case m.clone.cancelling:
209			b.WriteString("Cancelling — " + plural(m.clone.running(), "clone") + " finishing · ")
210		default:
211			b.WriteString(strconv.Itoa(found) + " found · ")
212		}
213		b.WriteString(strconv.Itoa(cloned) + " cloned · " + strconv.Itoa(present) + " already there")
214		if failed > 0 {
215			b.WriteString(" · " + strconv.Itoa(failed) + " failed")
216		}
217		return b.String()
218	}

