	}))
	t.Cleanup(f.server.Close)
	return f
}

// serverModel returns a laid-out model whose client talks to the fake API.
func serverModel(t *testing.T, f *fakeGitLab) Model {
	t.Helper()
	client, err := gitlab.NewClient(f.server.URL, "test-token")
