package explorer

import (
	"context"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
	"sync"

	tea "github.com/charmbracelet/bubbletea"
	gitlabclient "gitlab.com/gitlab-org/api/client-go"

	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/gitlab"
)

// The clone pipeline: a discovery walk feeding a bounded pool of clones
// (§3.16, decision 7).
//
// Building the whole list first and then cloning it would only move the dead
// screen one step earlier — the walk is what takes the minutes. Here a
// repository becomes a row the moment it is found and starts cloning as soon as
// a slot frees, so the list fills and the count climbs while the work happens.
//
// Nothing here touches the model. Everything the run needs is copied into a
// cloneSpec before the first goroutine starts, and the only way back is the
// event channel (Rule 110).

// cloneEventKind is what happened to one path.
type cloneEventKind int

const (
	// cloneFound: discovery turned up a repository. The row appears.
	cloneFound cloneEventKind = iota
	// cloneBegan: a slot freed and `git clone` started. The row spins.
	cloneBegan
	// cloneEnded: the clone finished, was skipped, or failed.
	cloneEnded
	// cloneWalkFailed: a group could not be listed. It is reported as its own
	// row rather than folded into a repository's error, because the repositories
	// under it were never discovered and no other row can stand for them.
	cloneWalkFailed
)

type cloneEvent struct {
	kind    cloneEventKind
	path    string
	skipped bool
	err     error
}

// cloneEventBuffer keeps the workers off the UI's critical path. Three events
// per repository, so this absorbs a burst of some seventy without a worker
// waiting on Update.
const cloneEventBuffer = 256

// cloneSpec is everything a run needs, read out of the model up front.
type cloneSpec struct {
	client    *gitlabclient.Client
	roots     []*TreeNode
	selection cloneSelection
	target    string
	// secrets is where the HTTPS token comes from. The storage rather than the
	// token itself, so the keyring read happens on the run's goroutine — Update
	// does no I/O.
	secrets         credentials.Storage
	cloneMethod     string
	gitlabURL       string
	jobs            int
	includeArchived bool
}

// cloneToken is the token the clones authenticate with, or "" for SSH and for
// a context whose secret store has nothing.
//
// A missing token is not an error here: a public repository clones without one,
// and a clone that does need it fails with git's own reason, on its own row.
func (s cloneSpec) cloneToken() string {
	if s.cloneMethod == "ssh" || s.secrets == nil {
		return ""
	}
	token, err := gitlab.NewAuth(s.secrets).LoadCredentials(s.gitlabURL)
	if err != nil {
		log.Printf("ERROR [explorer] loading the clone token: %v", err)
		return ""
	}
	return token
}

// cloneRun is a pipeline in flight.
type cloneRun struct {
	events <-chan cloneEvent
	// cancel stops **discovery only**. A `git clone` is never interrupted: a
	// context that kills one leaves half a repository on disk, which is exactly
	// the mess decision 12 exists to avoid. Cancelling therefore means the walk
	// stops and the scheduler issues no more work — the clones already running
	// are awaited, and the view says so.
	cancel context.CancelFunc
}

// startCloneRun launches the pipeline and returns immediately.
func startCloneRun(spec cloneSpec) *cloneRun {
	ctx, cancel := context.WithCancel(context.Background())
	events := make(chan cloneEvent, cloneEventBuffer)
	go runPipeline(ctx, spec, events)
	return &cloneRun{events: events, cancel: cancel}
}

// runPipeline walks the roots and clones what the walk finds.
func runPipeline(ctx context.Context, spec cloneSpec, events chan<- cloneEvent) {
	defer close(events)

	// Once, here, rather than per clone: the keyring is not free, and four
	// workers hitting it at the same time is four prompts on some backends.
	token := spec.cloneToken()

	found := make(chan *TreeNode)
	go func() {
		defer close(found)
		for _, root := range spec.roots {
			discover(ctx, spec, root, found, events)
		}
	}()

	var wg sync.WaitGroup
	slots := make(chan struct{}, max(spec.jobs, 1))

	for node := range found {
		if ctx.Err() != nil {
			break
		}
		events <- cloneEvent{kind: cloneFound, path: node.FullPath}
		slots <- struct{}{}
		wg.Add(1)
		go func(n *TreeNode) {
			defer wg.Done()
			defer func() { <-slots }()

			events <- cloneEvent{kind: cloneBegan, path: n.FullPath}
			skipped, err := cloneOne(n, spec, token)
			events <- cloneEvent{kind: cloneEnded, path: n.FullPath, skipped: skipped, err: err}
		}(node)
	}

	// Drain rather than abandon. Breaking out of the loop above leaves the walker
	// parked on a send nobody will ever read, and a goroutine holding a live HTTP
	// client is a leak that outlives the view.
	//
	//nolint:revive // the drain is the point; there is nothing to do with a node here
	for range found {
	}
	wg.Wait()
}

// discover walks one root, sending every included project to the pool.
//
// The selection is consulted on the way down, so an excluded subtree costs no
// requests at all: the walk simply does not enter it.
func discover(ctx context.Context, spec cloneSpec, node *TreeNode, found chan<- *TreeNode, events chan<- cloneEvent) {
	if ctx.Err() != nil || !spec.selection.includes(node.FullPath) {
		return
	}

	if node.Type == NodeTypeProject {
		select {
		case found <- node:
		case <-ctx.Done():
		}
		return
	}

	children, err := discoverGroupChildren(spec.client, node, spec.includeArchived)
	if err != nil {
		// A cancelled walk reports nothing: the error is the cancellation, and a
		// failed row for it would read as a repository nobody could clone.
		if ctx.Err() == nil {
			events <- cloneEvent{kind: cloneWalkFailed, path: node.FullPath, err: err}
		}
		return
	}
	for _, child := range children {
		discover(ctx, spec, child, found, events)
	}
}

// cloneOne clones a repository, or reports that it was already there.
//
// The destination mirrors the forge path in full (decision 4). Keeping only the
// last segment, as the old pull did, made `acme/platform` and `other/platform`
// land on the same directory and merge — which could not happen while one
// subtree was cloned at a time, and can now that several roots are confirmed at
// once.
func cloneOne(node *TreeNode, spec cloneSpec, token string) (skipped bool, err error) {
	dir := filepath.Join(spec.target, filepath.FromSlash(node.FullPath))
	if gitlab.DirExists(dir) {
		return true, nil
	}
	if err := os.MkdirAll(filepath.Dir(dir), 0o755); err != nil {
		return false, fmt.Errorf("mkdir %s: %w", filepath.Dir(dir), err)
	}
	url := cloneURL(spec.gitlabURL, spec.cloneMethod, node.FullPath)
	if err := gitlab.Clone(url, dir, gitlab.CloneOptions{Token: token}); err != nil {
		return false, err
	}
	return false, nil
}

// cloneURL builds the git URL for a project from the configured GitLab URL and
// the clone method. SSH form takes the host alone, so the scheme is stripped.
func cloneURL(gitlabURL, cloneMethod, fullPath string) string {
	cleanURL := strings.TrimSuffix(gitlabURL, "/")
	if cloneMethod != "ssh" {
		return fmt.Sprintf("%s/%s.git", cleanURL, fullPath)
	}

	host := strings.TrimPrefix(cleanURL, "https://")
	host = strings.TrimPrefix(host, "http://")
	return fmt.Sprintf("git@%s:%s.git", host, fullPath)
}

// waitForCloneEvent blocks on the run's channel and hands one event to Update.
// It is re-issued for each event, which is what keeps the model mutation in
// Update and the blocking read out of it.
func waitForCloneEvent(events <-chan cloneEvent) tea.Cmd {
	return func() tea.Msg {
		event, ok := <-events
		if !ok {
			return CloneRunFinishedMsg{}
		}
		return CloneEventMsg{event: event}
	}
}

package explorer

import (
	"log"
	"strconv"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
)

// The clone flow, end to end (§3.16):
//
//	c              → ModeSelecting, the tree with checkboxes
//	space          → tick the row; ←→ still drill, so deselecting means going in
//	enter          → borrow the workspaces view for a destination
//	                 (the selection survives the round trip — it names paths)
//	destination    → ModeCloning, the pipeline starts
//	esc            → cancel: discovery stops, running clones are awaited
//	esc (finished) → back to the tree, list discarded (decision 13)

// handleCloneStart enters the selection mode.
func (m Model) handleCloneStart() (tea.Model, tea.Cmd) {
	if m.shared.GitLabClient == nil || len(m.nodes) == 0 {
		return m, nil
	}
	m.mode = ModeSelecting
	m.selection = newCloneSelection()
	m.selectionNodes = map[string]*TreeNode{}
	m.updateTableRows()
	return m, nil
}

// handleSelectionToggle ticks or unticks the row under the cursor (Space,
// Rule 135).
//
// The node is kept beside the path because the walk needs somewhere to start
// and a root ticked three levels down is not reachable from the current level
// once the user has come back up. The selection itself stays paths-only — it
// has to answer for descendants nobody has fetched.
func (m Model) handleSelectionToggle() (tea.Model, tea.Cmd) {
	node, ok := m.selectedNode()
	if !ok {
		return m, nil
	}

	m.selection.toggle(node.FullPath)
	if m.selection.isRoot(node.FullPath) {
		m.selectionNodes[node.FullPath] = node
	} else {
		delete(m.selectionNodes, node.FullPath)
	}
	m.updateTableRows()
	return m, nil
}

// handleSelectionConfirm asks the app for a destination directory.
func (m Model) handleSelectionConfirm() (tea.Model, tea.Cmd) {
	if m.selection.isEmpty() {
		m.footerInfo = "Nothing selected — press space to tick a group or a project"
		return m, clearFooterMsgCmd()
	}
	return m, func() tea.Msg { return CloneSelectionRequestMsg{} }
}

// handleSelectionCancel leaves the selection mode, dropping the selection.
func (m Model) handleSelectionCancel() (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.updateTableRows()
	return m, nil
}

// handleCloneDestinationSelected starts the pipeline.
func (m Model) handleCloneDestinationSelected(msg CloneDestinationSelectedMsg) (tea.Model, tea.Cmd) {
	roots := m.rootNodes()
	if len(roots) == 0 {
		// The selection survived the round trip but named nothing reachable,
		// which is a bug rather than a user action — say so instead of opening
		// an empty list.
		log.Printf("ERROR [explorer] clone: the selection resolved to no nodes")
		m.footerError = "Nothing to clone — check logs"
		return m.handleSelectionCancel()
	}

	run := startCloneRun(cloneSpec{
		client:          m.shared.GitLabClient,
		roots:           roots,
		selection:       m.selection,
		target:          msg.Path,
		secrets:         m.shared.Secrets.Storage,
		cloneMethod:     m.config.GitLab.CloneMethod,
		gitlabURL:       m.config.GitLab.URL,
		jobs:            m.config.GitLab.Pull.ParallelJobs,
		includeArchived: m.config.GitLab.Pull.IncludeArchived,
	})

	m.mode = ModeCloning
	m.clone = newCloneList(msg.Path, run)
	m.clone.table.Resize(m.width, max(m.height-1, 1))
	return m, tea.Batch(m.spinner.Tick, waitForCloneEvent(run.events))
}

// rootNodes resolves the ticked paths to the nodes the walk starts from, in a
// stable order so two runs of the same selection read the same way.
func (m Model) rootNodes() []*TreeNode {
	paths := m.selection.rootPaths()
	nodes := make([]*TreeNode, 0, len(paths))
	for _, path := range paths {
		if node, ok := m.selectionNodes[path]; ok {
			nodes = append(nodes, node)
		}
	}
	return nodes
}

// handleCloneEvent folds one pipeline event in and waits for the next.
func (m Model) handleCloneEvent(msg CloneEventMsg) (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}
	if msg.event.kind == cloneEnded && msg.event.err != nil {
		log.Printf("ERROR [explorer] clone %s: %v", msg.event.path, msg.event.err)
	}
	if msg.event.kind == cloneWalkFailed {
		log.Printf("ERROR [explorer] discover %s: %v", msg.event.path, msg.event.err)
	}
	m.clone.apply(msg.event)
	return m, waitForCloneEvent(m.clone.run.events)
}

// handleCloneRunFinished is the closed channel: every clone has returned.
func (m Model) handleCloneRunFinished() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}
	m.clone.finished = true

	// Decision 13 keeps only what workspaces can show, and a failed clone wrote
	// nothing. Naming the failures now is the only record there will be.
	if failed := m.clone.failures(); len(failed) > 0 {
		m.footerError = failureSummary(failed)
		return m, clearFooterMsgCmd()
	}
	return m, nil
}

// failureSummary names one failure and counts the rest — the footer is one line.
func failureSummary(failed []string) string {
	if len(failed) == 1 {
		return "Failed to clone " + failed[0] + " — check logs"
	}
	return "Failed to clone " + failed[0] + " and " +
		plural(len(failed)-1, "other") + " — check logs"
}

func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return strconv.Itoa(n) + " " + word + "s"
}

// handleCloneEsc cancels a running pipeline, or closes a finished one.
//
// The two are one key because they are one intent — "I am done with this" — and
// separating them would need the user to know which state the list is in. A
// second press while cancelling does nothing: forcing would mean killing a
// `git clone` mid-write, which is the half-repository decision 12 rules out.
func (m Model) handleCloneEsc() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		m.mode = ModeNormal
		return m, nil
	}
	if m.clone.finished {
		return m.handleCloneClose()
	}
	if m.clone.cancelling {
		return m, nil
	}

	m.clone.cancelling = true
	m.clone.run.cancel()
	return m, nil
}

// handleCloneClose discards the list and returns to the tree.
func (m Model) handleCloneClose() (tea.Model, tea.Cmd) {
	m.clone = nil
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.mode = ModeNormal
	m.updateTableRows()
	return m, nil
}

// cloneStatusLine is what the view puts under the list: what the run is doing,
// then what it did.
func (m Model) cloneStatusLine() string {
	if m.clone == nil {
		return ""
	}
	found, cloned, present, failed := m.clone.counts()

	var b strings.Builder
	switch {
	case m.clone.finished:
		b.WriteString("Done — ")
	case m.clone.cancelling:
		b.WriteString("Cancelling — " + plural(m.clone.running(), "clone") + " finishing · ")
	default:
		b.WriteString(strconv.Itoa(found) + " found · ")
	}
	b.WriteString(strconv.Itoa(cloned) + " cloned · " + strconv.Itoa(present) + " already there")
	if failed > 0 {
		b.WriteString(" · " + strconv.Itoa(failed) + " failed")
	}
	return b.String()
}

package gitlab

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// CloneOptions is what a clone needs beyond the URL.
type CloneOptions struct {
	// Token authenticates over HTTPS. Empty means the clone is expected to
	// succeed without one — SSH, or a public repository.
	Token string
}

// Clone clones a Git repository to the target path.
//
// repoURL is the full URL to clone (HTTPS or SSH); targetPath is the absolute
// path where the repo should be cloned.
//
// **Nothing here may prompt.** DevDesk owns the terminal, and a `git` that
// wants credentials does not simply fail: stdin is the null device, so git's
// own prompt is skipped and the *credential helper* takes over. A helper is a
// separate process — Git Credential Manager on Windows — which writes its
// `info: please complete authentication in your browser` to the console
// directly, over the top of the rendered frame, and then waits. The frame is
// corrupted, the row spins for ever, and nothing on screen says why.
//
// So the environment forbids every interactive path, and the token DevDesk
// already holds is passed in instead. A clone that still cannot authenticate
// fails immediately, with git's own reason.
func Clone(repoURL, targetPath string, opts CloneOptions) error {
	cmd := exec.Command("git", "clone", repoURL, targetPath)
	cmd.Env = cloneEnv(opts)

	// stdin is the null device, and stdout/stderr are captured rather than
	// merely discarded: git's reason for failing is the only thing the row's
	// Detail column has to show.
	var stderr bytes.Buffer
	cmd.Stdin = nil
	cmd.Stdout = nil
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if reason := lastLine(stderr.String()); reason != "" {
			return fmt.Errorf("%s", reason)
		}
		return err
	}
	return nil
}

// cloneEnv builds the environment one clone runs under.
func cloneEnv(opts CloneOptions) []string {
	env := append(os.Environ(),
		// git's own prompt, the credential helper's browser flow, and the two
		// askpass hooks. All four are ways for a child process to take the
		// terminal, and all four are off.
		"GIT_TERMINAL_PROMPT=0",
		"GCM_INTERACTIVE=never",
		"GIT_ASKPASS=",
		"SSH_ASKPASS=",
		// SSH has prompts of its own — a key passphrase, an unknown host key.
		// BatchMode turns both into an immediate failure, which is a row that
		// says so rather than a row that never moves.
		"GIT_SSH_COMMAND=ssh -o BatchMode=yes",
	)

	// A stalled transfer is aborted by git itself rather than by killing the
	// process. That matters: git cleans up the directory it was writing into,
	// so a clone still never leaves half a repository behind (§3.16,
	// decision 12).
	config := [][2]string{
		{"http.lowSpeedLimit", "1000"},
		{"http.lowSpeedTime", "60"},
	}
	if opts.Token != "" {
		// Basic with `oauth2` as the username is GitLab's documented form for a
		// personal access token over HTTPS.
		//
		// It travels in the environment, not in argv: a command line is
		// readable from the process list by anyone on the machine, and it would
		// also be the token, in the clear, once per clone. Nor does it go in the
		// URL — that form is written into every cloned repository's
		// .git/config and stays there.
		credential := base64.StdEncoding.EncodeToString([]byte("oauth2:" + opts.Token))
		config = append(config, [2]string{"http.extraHeader", "Authorization: Basic " + credential})
	}

	env = append(env, fmt.Sprintf("GIT_CONFIG_COUNT=%d", len(config)))
	for i, kv := range config {
		env = append(env,
			fmt.Sprintf("GIT_CONFIG_KEY_%d=%s", i, kv[0]),
			fmt.Sprintf("GIT_CONFIG_VALUE_%d=%s", i, kv[1]),
		)
	}
	return env
}

// lastLine returns the final non-empty line of git's stderr, which is where it
// puts the reason. The lines above it are progress.
func lastLine(output string) string {
	lines := strings.Split(strings.ReplaceAll(output, "\r", "\n"), "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if line := strings.TrimSpace(lines[i]); line != "" {
			return line
		}
	}
	return ""
}

// DirExists checks if a directory exists at the given path
func DirExists(path string) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package gitlab

import (
	"encoding/base64"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

// requireGit skips the test when no git binary is available.
func requireGit(t *testing.T) {
	t.Helper()
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not found in PATH")
	}
}

// seedRepo creates a git repository holding a single committed file and returns
// its path. Identity and signing are forced on the command line so the test does
// not depend on the machine's git configuration.
func seedRepo(t *testing.T) string {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "source")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("creating source dir: %v", err)
	}

	run := func(args ...string) {
		t.Helper()
		cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}

	run("init", "--initial-branch=main")
	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# seed\n"), 0o600); err != nil {
		t.Fatalf("writing README: %v", err)
	}
	run("add", "README.md")
	run("-c", "user.name=devdesk", "-c", "user.email=devdesk@example.com",
		"-c", "commit.gpgsign=false", "commit", "-m", "seed")

	return dir
}

func TestCloneCopiesRepositoryContents(t *testing.T) {
	requireGit(t)
	source := seedRepo(t)
	target := filepath.Join(t.TempDir(), "clone")

	if err := Clone(source, target, CloneOptions{}); err != nil {
		t.Fatalf("Clone() error = %v", err)
	}

	if _, err := os.Stat(filepath.Join(target, "README.md")); err != nil {
		t.Errorf("cloned repo is missing README.md: %v", err)
	}
	if !DirExists(filepath.Join(target, ".git")) {
		t.Error("cloned repo has no .git directory")
	}
}

func TestCloneFailsOnMissingSource(t *testing.T) {
	requireGit(t)
	source := filepath.Join(t.TempDir(), "does-not-exist")
	target := filepath.Join(t.TempDir(), "clone")

	if err := Clone(source, target, CloneOptions{}); err == nil {
		t.Error("Clone() from a missing source returned no error")
	}
}

func TestCloneFailsWhenTargetIsNotEmpty(t *testing.T) {
	requireGit(t)
	source := seedRepo(t)
	target := t.TempDir()
	if err := os.WriteFile(filepath.Join(target, "existing.txt"), []byte("x"), 0o600); err != nil {
		t.Fatalf("writing existing file: %v", err)
	}

	if err := Clone(source, target, CloneOptions{}); err == nil {
		t.Error("Clone() into a non-empty directory returned no error")
	}
}

// A failure reports git's own reason. It is what the clone list's Detail column
// shows, and without it a failed row says only that something went wrong.
func TestCloneReportsGitsReason(t *testing.T) {
	requireGit(t)
	source := filepath.Join(t.TempDir(), "does-not-exist")

	err := Clone(source, filepath.Join(t.TempDir(), "clone"), CloneOptions{})

	if err == nil {
		t.Fatal("Clone() from a missing source returned no error")
	}
	// "exit status 128" is what the bare ExitError says, and it is what this
	// used to return: git's stderr went to the null device.
	if strings.HasPrefix(err.Error(), "exit status") {
		t.Errorf("Clone() reported only an exit status: %v", err)
	}
	if !strings.Contains(strings.ToLower(err.Error()), "repository") {
		t.Errorf("Clone() error does not name the problem: %v", err)
	}
}

// Nothing a clone runs may prompt. DevDesk owns the terminal: git's own prompt
// is skipped because stdin is the null device, so the *credential helper* takes
// over — a separate process that writes to the console over the rendered frame
// and then waits for a browser. The row spins for ever and the screen is
// corrupted, which is what was observed.
func TestTheCloneEnvironmentForbidsEveryPrompt(t *testing.T) {
	env := cloneEnv(CloneOptions{})

	for _, want := range []string{
		"GIT_TERMINAL_PROMPT=0", // git's own prompt
		"GCM_INTERACTIVE=never", // Git Credential Manager's browser flow
		"GIT_ASKPASS=",          // the GUI hook git would fall back to
		"SSH_ASKPASS=",          // and ssh's
	} {
		if !slices.Contains(env, want) {
			t.Errorf("the clone environment is missing %q", want)
		}
	}
	// BatchMode covers ssh's own two prompts: a key passphrase and an unknown
	// host key. Both otherwise hang exactly the same way.
	if !slices.ContainsFunc(env, func(v string) bool {
		return strings.HasPrefix(v, "GIT_SSH_COMMAND=") && strings.Contains(v, "BatchMode=yes")
	}) {
		t.Error("the clone environment does not put ssh in batch mode")
	}
}

// A stalled transfer is aborted by git, not by killing it: git cleans up the
// directory it was writing into, so a clone still never leaves half a
// repository behind (§3.16, decision 12).
func TestTheCloneEnvironmentBoundsAStalledTransfer(t *testing.T) {
	env := cloneEnv(CloneOptions{})

	if !slices.Contains(env, "GIT_CONFIG_KEY_0=http.lowSpeedLimit") {
		t.Errorf("no low-speed abort is configured:\n%v", gitConfigOf(env))
	}
	if !slices.Contains(env, "GIT_CONFIG_KEY_1=http.lowSpeedTime") {
		t.Errorf("no low-speed window is configured:\n%v", gitConfigOf(env))
	}
}

// The token travels in the environment. A command line is readable from the
// process list by anyone on the machine, and the URL form is written into every
// cloned repository's .git/config and stays there.
func TestTheTokenTravelsInTheEnvironmentAsBasicAuth(t *testing.T) {
	env := cloneEnv(CloneOptions{Token: "glpat-secret"})

	want := "Authorization: Basic " + base64.StdEncoding.EncodeToString([]byte("oauth2:glpat-secret"))
	if !slices.Contains(env, "GIT_CONFIG_VALUE_2="+want) {
		t.Errorf("the token is not passed as a Basic header:\n%v", gitConfigOf(env))
	}
	if !slices.Contains(env, "GIT_CONFIG_COUNT=3") {
		t.Errorf("GIT_CONFIG_COUNT does not cover the header:\n%v", gitConfigOf(env))
	}
}

// No token means no header, and a count that still matches what is set — an
// over-count makes git fail on every clone, including the public ones that
// need no token at all.
func TestWithoutATokenTheHeaderIsAbsentAndTheCountMatches(t *testing.T) {
	env := cloneEnv(CloneOptions{})

	if !slices.Contains(env, "GIT_CONFIG_COUNT=2") {
		t.Errorf("GIT_CONFIG_COUNT does not match what is set:\n%v", gitConfigOf(env))
	}
	for _, v := range env {
		if strings.Contains(v, "Authorization") {
			t.Errorf("an empty token still produced a header: %q", v)
		}
	}
}

// gitConfigOf returns the GIT_CONFIG_* entries, for failure messages.
func gitConfigOf(env []string) []string {
	var out []string
	for _, v := range env {
		if strings.HasPrefix(v, "GIT_CONFIG_") {
			out = append(out, v)
		}
	}
	return out
}

func TestLastLineIsGitsReasonNotItsProgress(t *testing.T) {
	tests := []struct {
		name   string
		output string
		want   string
	}{
		{"the reason is last", "Cloning into 'x'...\nfatal: repository not found\n", "fatal: repository not found"},
		{"carriage returns are progress", "remote: Counting\rremote: Done\rfatal: boom\n", "fatal: boom"},
		{"trailing blank lines", "fatal: boom\n\n\n", "fatal: boom"},
		{"nothing at all", "   \n\n", ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := lastLine(tt.output); got != tt.want {
				t.Errorf("lastLine() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestDirExists(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "file.txt")
	if err := os.WriteFile(file, []byte("x"), 0o600); err != nil {
		t.Fatalf("writing file: %v", err)
	}

	tests := []struct {
		name string
		path string
		want bool
	}{
		{"existing directory", dir, true},
		{"nested missing path", filepath.Join(dir, "nope", "deeper"), false},
		{"a file is not a directory", file, false},
		{"empty path", "", false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := DirExists(tt.path); got != tt.want {
				t.Errorf("DirExists(%q) = %v, want %v", tt.path, got, tt.want)
			}
		})
	}
}

