182	// formatProjectType formats the project type column with Nerd Font icons
183	func formatProjectType(entry Entry) string {
184		switch entry.ProjectType {
185		case "Go":
186			return theme.IconGo
187		case "Rust":
188			return theme.IconRust
189		case "Node":
190			return theme.IconNode
191		case "Python":
192			return theme.IconPython
193		case "Java":
194			return theme.IconJava
195		case "Ruby":
196			return theme.IconRuby
197		case "PHP":
198			return theme.IconPHP
199		case "Elixir":
200			return theme.IconElixir
201		case "Make":
202			return theme.IconTools
203		case "Docker":
204			return theme.IconDocker
205		default:
206			return ""
207		}
208	}
209	
210	// formatScanColumns returns the SENSITIVE, C, H, M, L, SCANNED column values for an entry.
211	// For git repos: looks up the scan cache directly.
212	// For directories: aggregates sub-repo scan entries.
213	func (m *Model) formatScanColumns(entry Entry, frame string) (sensitive, c, h, med, l, scanned string) {
214		dash := "-"
215		empty := ""
216	
217		if entry.IsGitRepo {
218			if m.scanningPaths[entry.Path] {
219				return empty, dash, dash, dash, dash, frame + " scanning"
220			}
221			scanEntry, ok := m.scanCache[entry.Path]
222			if !ok {
223				return dash, dash, dash, dash, dash, dash
224			}
225			return formatSecrets(scanEntry.Sensitive, true),
226				fmt.Sprintf("%d", scanEntry.Critical),
227				fmt.Sprintf("%d", scanEntry.High),
228				fmt.Sprintf("%d", scanEntry.Medium),
229				fmt.Sprintf("%d", scanEntry.Low),
230				theme.IconPending + " " + timeAgo(scanEntry.ScannedAt)
231		}
232	
233		// Files are not scannable — return empty columns
234		if !entry.IsDir {
235			return empty, empty, empty, empty, empty, empty
236		}
237	
238		// Directory: aggregate sub-repos
239		if len(entry.SubRepoPaths) == 0 {
240			return theme.IconWorkspaceUnknown, empty, empty, empty, empty, empty
241		}
242	
243		// Count how many sub-repos are currently scanning
244		scanningCount := 0
245		for _, repoPath := range entry.SubRepoPaths {
246			if m.scanningPaths[repoPath] {
247				scanningCount++
248			}
249		}
250	
251		var scannedEntries []cache.WorkspaceScanEntry
252		for _, repoPath := range entry.SubRepoPaths {
253			if e, ok := m.scanCache[repoPath]; ok {
254				scannedEntries = append(scannedEntries, e)
255			}
256		}
257	
258		if len(scannedEntries) == 0 && scanningCount == 0 {
259			return dash, empty, empty, empty, empty, dash
260		}
261		if len(scannedEntries) == 0 && scanningCount > 0 {
262			return empty, dash, dash, dash, dash, frame + " scanning"
263		}
264	
265		totalC, totalH, totalM, totalL := 0, 0, 0, 0
266		hasSensitive := false
267		for _, e := range scannedEntries {
268			totalC += e.Critical
269			totalH += e.High
270			totalM += e.Medium
271			totalL += e.Low
272			if e.Sensitive {
273				hasSensitive = true
274			}
275		}
276	
277		scannedCount := len(scannedEntries)
278		totalCount := len(entry.SubRepoPaths)
279		scanned = theme.IconDirectory + " " + fmt.Sprintf("%d/%d", scannedCount, totalCount)
280	
281		return formatSecrets(hasSensitive, scannedCount > 0),
282			fmt.Sprintf("%d", totalC),
283			fmt.Sprintf("%d", totalH),
284			fmt.Sprintf("%d", totalM),
285			fmt.Sprintf("%d", totalL),
286			scanned
287	}
288	
289	// formatSecrets returns the Secrets column icon as plain text (Rule 122: no ANSI in table cells)
290	func formatSecrets(sensitive bool, scanDone bool) string {
291		if !scanDone {
292			return theme.IconWorkspaceUnknown
293		}
294		if sensitive {
295			return theme.IconWorkspaceUntrusted
296		}
297		return theme.IconWorkspaceTrusted
298	}
