119	// handleWorkspaceScanComplete processes the result of a completed workspace scan (Rule 128).
120	func (m Model) handleWorkspaceScanComplete(msg WorkspaceScanCompleteMsg) (tea.Model, tea.Cmd) {
121		delete(m.scanningPaths, msg.RepoPath)
