2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7	
8		tea "github.com/charmbracelet/bubbletea"
9	)
10	
11	// updateTableSize adjusts table dimensions.
12	//
13	// Rule 124: the footer (tab bar + filter bar) is outside the viewport, so only
14	// the table's own header row is subtracted. The Rule 116 arithmetic, the
15	// selected row's width and the cursor clamp are the component's now.
16	func (m *Model) updateTableSize() {
17		m.table.Resize(m.width, max(m.height-1, 1))
18	}
19	
20	// setEntries replaces the listing and rebuilds the decoration over it.
21	func (m *Model) setEntries(entries []Entry) {
22		m.table.SetItems(m.rowsFor(entries))
23	}
24	
25	// refreshRows redecorates the entries the table already holds. Callers reach it
26	// after a scan starts, finishes or arrives from the cache: the listing has not
27	// changed, only what the six scan columns say about it.
28	func (m *Model) refreshRows() {
29		m.setEntries(m.entries())
30	}
31	
32	// entries returns the current directory listing, filter or no filter.
33	func (m Model) entries() []Entry {
34		out := make([]Entry, 0, len(m.table.Items()))
35		for _, row := range m.table.Items() {
36			out = append(out, row.Entry)
37		}
38		return out
39	}
40	
41	// selectedEntry returns the entry under the cursor.
42	//
43	// Every action used to index the *unfiltered* list with a cursor into the
44	// filtered rows, so under a filter they acted on a different directory from the
45	// one highlighted, and ctrl+d asked to delete it (D24). The table resolves the
46	// cursor against the slice its rows were built from, so the two cannot part.
47	func (m Model) selectedEntry() (Entry, bool) {
48		row, ok := m.table.Selected()
49		return row.Entry, ok
50	}
51	
52	// loadEntries loads the contents of the current directory with enriched metadata
53	func (m Model) loadEntries() tea.Cmd {
54		currentPath := m.currentPath
55		workspacesDir := m.getExpandedWorkspacesDir()
56	
57		return func() tea.Msg {
58			targetDir := workspacesDir
59			if currentPath != "" {
60				targetDir = currentPath
61			}
62	
63			// Check if directory exists, create it if it doesn't (only for workspaces root)
64			if _, err := os.Stat(targetDir); os.IsNotExist(err) {
65				if currentPath == "" {
66					if err := os.MkdirAll(targetDir, 0755); err != nil {
67						return LoadErrorMsg{Error: err}
68					}
69					return EntriesLoadedMsg{Entries: []Entry{}}
70				}
71				return LoadErrorMsg{Error: err}
72			}
73	
74			dirEntries, err := os.ReadDir(targetDir)
75			if err != nil {
76				return LoadErrorMsg{Error: err}
77			}
78	
79			entries := make([]Entry, 0, len(dirEntries))
80			for _, dirEntry := range dirEntries {
81				// Skip hidden files/directories
82				if strings.HasPrefix(dirEntry.Name(), ".") {
83					continue
84				}
85	
86				info, err := dirEntry.Info()
87				if err != nil {
88					continue
89				}
90	
91				entry := Entry{
92					Name:    dirEntry.Name(),
93					Path:    filepath.Join(targetDir, dirEntry.Name()),
