// a dozen times — the same reason the clone pipeline loads its token once.
func TestTheSyncTokenIsLoadedAtMostOnce(t *testing.T) {
	calls := 0
	load := func() string {
		calls++
		return "glpat-secret"
	}

	for range 5 {
