185	// holds it, so the Git Status column stops describing the state before the sync.
186	//
187	// Only the git fields move: Name, Path, ModTime and the project type belong to
188	// the listing, and the sync had no reason to look at them.
189	//
190	// The rows are rebuilt whether or not the repository is still among them — that
191	// rebuild is also what takes the spinner off, and a row that vanished mid-sync
192	// (a reload, a drill-down) must not leave the ones still on screen stale.
193	func (m *Model) applyGitStatus(repoPath string, status Entry) {
194		entries := m.entries()
195		for i := range entries {
196			if entries[i].Path != repoPath || !status.IsGitRepo {
197				continue
198			}
199			entries[i].GitBranch = status.GitBranch
200			entries[i].GitRemote = status.GitRemote
201			entries[i].GitRemoteURL = status.GitRemoteURL
202			entries[i].GitModified = status.GitModified
203			entries[i].GitUntracked = status.GitUntracked
204			entries[i].GitUnpushed = status.GitUnpushed
205			entries[i].GitUnpulled = status.GitUnpulled
206		}
207		m.setEntries(entries)
208	}
209	
210	// tokenForRemote returns the configured GitLab token when the repository's
211	// remote is on the configured GitLab host, and "" otherwise.
212	//
213	// A personal access token authenticates one host. The workspaces view holds
214	// whatever the user has cloned — GitHub, a customer's Gitea, a bare path on a
215	// network share — and offering DevDesk's GitLab credential to any of them would
216	// hand it to a third party over the wire. So the host has to match, and a
217	// repository elsewhere fetches anonymously or fails saying so.
218	func tokenForRemote(remoteURL, gitlabURL string, load func() string) string {
219		host := hostOf(normalizeRemoteURL(remoteURL))
220		if host == "" || !strings.EqualFold(host, hostOf(gitlabURL)) {
221			return ""
222		}
223		return load()
224	}
225	
226	// hostOf returns a URL's host, lowercased and without a port.
227	func hostOf(rawURL string) string {
228		parsed, err := url.Parse(rawURL)
229		if err != nil {
230			return ""
231		}
232		return strings.ToLower(parsed.Hostname())
233	}

