// spinnerTickIfIdle restarts the spinner chain, unless something is already
// keeping it alive. handleSpinnerTick stops scheduling once nothing is running,
// so a rescan has to start it again — and starting a second chain alongside a
// live one makes the frames advance at twice the rate.
func (m Model) spinnerTickIfIdle() tea.Cmd {
	if m.inventoryScanning() {
		return nil
	}
	return m.spinner.Tick
}

// rescanAll purges every entry and rescans every target (Rule 126).
//
// The rows themselves stay: they are the list of what is known to have been
// scanned, and dropping them would leave an empty view for as long as the scans
// take — and lose the targets entirely if the application were closed meanwhile.
=== update ===
	case InventoryScanFinishedMsg:
		return m.handleInventoryScanFinished(msg)

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	}

	return m, nil
}

// handleSpinnerTick advances the spinner while a rescan is running.
//
// The frame is a table cell rather than a scanning screen, and one that never
// advances reads as a hung scan. The rows carry it, so they are restamped — but
// only while something is running, since SetItems re-filters and re-sorts and
// there is no reason to do that sixty times a second for a settled table.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.inventoryScanning() {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	m.setInventory(m.inventory.Items())
	return m, cmd
}

